// Objeto reservado para transcrever o texto de cada página
const textosPaginas = {
  1: "Página 1:\n• Capítulo 1 — A Ginga Começa\nMuito antes de Kewyn se tornar conhecido como um dos mais habilidosos ninjas do Clã Ginga, ele era apenas uma criança.\nUm garoto curioso, inquieto e que nunca conseguia ficar parado.\nEle vivia na Vila da Ginga, uma pequena vila ninja escondida entre enormes montanhas e uma floresta cheia de rios.\nDiferente das outras vilas, a Vila da Ginga tinha uma tradição que fazia parte da vida de todos os seus habitantes:\na capoeira.\nPara os membros do Clã Ginga, capoeira não era apenas uma dança.\nEra uma arte de combate.\nEra uma maneira de se movimentar.\nEra uma forma de pensar.\nDesde pequenos, os membros do clã aprendiam a gingar antes mesmo de aprenderem a controlar completamente o chakra.\nA primeira lição era simples:\n\"Não fique parado diante do perigo.\"",
  2: "Página 2:\n• O pequeno Kewyn\nKewyn tinha oito anos.\nNaquela época, seus dois olhos eram completamente normais, castanhos, e ele ainda não havia despertado o verdadeiro poder de sua linhagem.\nEle treinava todos os dias com outras crianças do clã.\nEnquanto algumas crianças preferiam treinar kunais e shurikens, Kewyn gostava mesmo era de lutar usando as pernas.\n— Você nunca vai aprender a lutar direito desse jeito! — reclamou um garoto depois de cair no chão.\nKewyn abriu um sorriso.\n— Mas eu ganhei.\n— Você trapaceou!\n— Capoeira não é trapaça.\nKewyn entrou novamente na posição de ginga.\nO garoto avançou.\nKewyn desviou para o lado, colocou uma das mãos no chão e passou as pernas por cima do adversário.\nO menino perdeu o equilíbrio e caiu novamente.\nAs outras crianças começaram a rir.\n— De novo! — gritou Kewyn.",
  3: "Página 3:\nFoi naquele momento que um dos professores apareceu.\n— Kewyn.\nO garoto parou.\n— Sim, professor?\n— Você é rápido.\nTem equilíbrio e sabe observar seus adversários.\nKewyn sorriu.\n— Então eu sou bom?\nO professor cruzou os braços.\n— Não.\nO sorriso desapareceu.\n— Ainda não.\nKewyn ficou determinado.\n— Então eu vou ficar bom.\nO professor sorriu discretamente.\n— É isso que eu queria ouvir.",
  4: "Página 4:\n• Abriely\nDo outro lado da vila, uma garota também treinava.\nSeu nome era Abriely.\nEla era diferente de Kewyn.\nEnquanto Kewyn era impulsivo e adorava entrar em uma luta sem pensar duas vezes, Abriely era mais tranquila.\nEla gostava de observar.\nGostava de ajudar os outros.\nE tinha uma ligação incomum com a água.\nQuando tinha apenas oito anos, Abriely já conseguia sentir a presença de pequenas quantidades de água ao seu redor.\nDurante um treinamento, o professor colocou uma pequena tigela de água diante dela.\n— Concentre seu chakra.\nAbriely fechou os olhos.\nRespirou profundamente.\nA água começou a tremer.\nUma pequena gota se levantou da tigela.\nAs crianças ficaram impressionadas.\n— Ela conseguiu!\nAbriely abriu os olhos.\nA gota caiu.\nEla sorriu.\n— Eu consigo fazer de novo.\nO professor respondeu:\n— Você vai conseguir muito mais do que isso algum dia.\nNaquele momento, ninguém imaginava que aquela pequena habilidade acabaria se transformando em um dos poderes mais raros da história do Clã Ginga.",
  5: "Página 5:\n• Rodrigo\nRodrigo era o mais estudioso dos quatro.\nEle usava óculos desde criança e passava muito tempo lendo livros sobre chakra, técnicas ninja e história dos clãs.\nMas existia uma coisa que ele adorava tanto quanto estudar:\ncapoeira.\nRodrigo não tinha a força de Kewyn.\nNão tinha a afinidade natural de Abriely com a água.\nMas tinha uma inteligência impressionante.\nEle observava os movimentos dos outros e tentava descobrir seus padrões.\nDurante um treinamento, Kewyn tentou acertá-lo com um chute.\nRodrigo desviou.\nKewyn atacou novamente.\nRodrigo desviou outra vez.\n— Para de fugir! — reclamou Kewyn.\nRodrigo ajeitou os óculos.\n— Eu não estou fugindo.\n— Então está fazendo o quê?\n— Estudando você.\nKewyn ficou confuso.\nRodrigo sorriu.\n— Você sempre começa os ataques usando a perna direita.\nKewyn arregalou os olhos.\n— Como você sabe?\n— Porque eu prestei atenção.\nKewyn ficou em silêncio.\nEntão começou a sorrir.\n— Então vamos ver se você consegue prever o próximo.\nOs dois começaram a lutar novamente.",
  6: "Página 6:\n• Nicolas\nNicolas era completamente diferente de Rodrigo.\nEle era energético.\nCompetitivo.\nE odiava perder.\nQuando treinava, sempre tentava fazer mais uma repetição, mais um chute, mais uma corrida.\n— Eu vou ser o ninja mais rápido da vila! — dizia.\nOs professores riam.\n— Você ainda precisa aprender a controlar seu chakra.\n— Eu vou aprender!\nNicolas tinha uma afinidade natural com o Raiton, o elemento raio.\nMas naquela idade ele ainda não conseguia produzir eletricidade de verdade.\nÀs vezes, durante seus treinamentos, pequenas faíscas apareciam em seus dedos.\nQuando isso acontecia, Nicolas ficava animado.\n— Vocês viram?!\nKewyn respondia:\n— Foi só uma faísca.\n— Uma faísca que você não consegue fazer!\n— Consigo sim!\n— Então faz!\nKewyn tentava.\nNada acontecia.\nNicolas começava a rir.\n— Hahahaha!\nKewyn ficava irritado.\n— Para de rir!\nAbriely e Rodrigo observavam os dois.\nRodrigo ajeitava os óculos.\n— Vocês dois são crianças.\n— E você também! — responderam Kewyn e Nicolas ao mesmo tempo.",
  7: "Página 7:\n• O dia da Academia\nAlguns anos se passaram.\nOs quatro chegaram à idade de entrar oficialmente na Academia Ninja.\nAquele era o primeiro passo para se tornarem ninjas.\nNa Academia, aprenderiam:\n\ncontrole de chakra;\ntécnicas básicas;\narremesso de kunai;\nshuriken;\ntransformação;\nclonagem;\ncombate corpo a corpo;\nestratégia;\ne, principalmente, controle emocional.\nMas o Clã Ginga tinha uma matéria especial.\nCombate Ginga.\nEra o treinamento de capoeira usado pelos ninjas do clã.\nO professor entrou na sala.\n— Crianças, hoje vocês começarão o treinamento que decidirá quem está preparado para se tornar um verdadeiro ninja.\nTodos ficaram em silêncio.\nKewyn estava animado.\nNicolas estava sorrindo.\nAbriely estava concentrada.\nRodrigo ajeitou os óculos.\nO professor colocou quatro pequenos objetos sobre a mesa.\n— Cada um de vocês deverá demonstrar controle de chakra.",
  8: "Página 8:\nKewyn foi o primeiro.\nEle fechou os olhos.\nRespirou.\nTentou concentrar chakra nas mãos.\nNada aconteceu.\n— Concentre-se — disse o professor.\nKewyn tentou novamente.\nDessa vez, uma pequena quantidade de chakra apareceu.\nO professor assentiu.\n— Está melhorando.\nDepois foi Abriely.\nEla conseguiu controlar o chakra com facilidade.\nRodrigo também conseguiu.\nNicolas tentou com tanta força que acabou caindo para trás.\nAs crianças começaram a rir.\nNicolas levantou rapidamente.\n— Eu fiz de propósito!\nKewyn começou a rir.\n— Claro que fez.\n— Cala a boca!",
  9: "Página 9:\n• A primeira missão\nDepois de meses de treinamento, os quatro chegaram ao exame final da Academia.\nEles ainda não eram Genin.\nPrecisavam provar que estavam preparados.\nO exame tinha três partes.\nPrimeiro, uma prova escrita.\nRodrigo terminou rapidamente.\nAbriely foi muito bem.\nKewyn ficou olhando para a folha.\n— Professor...\n— O que foi?\n— Posso desenhar?\n— Não.\nNicolas começou a rir.\nDepois veio a segunda prova.\nArremesso de kunai.\nNicolas foi excelente.\nRodrigo acertou os alvos com precisão.\nAbriely teve um desempenho equilibrado.\nKewyn não foi o melhor no arremesso, mas conseguiu compensar usando sua movimentação.",
  10: "Página 10:\nFinalmente veio a terceira prova.\nCombate.\nKewyn entrou na arena.\nSeu adversário era maior.\nO garoto avançou.\nKewyn gingou.\nEsquerda.\nDireita.\nEsquerda.\nO adversário tentou agarrá-lo.\nKewyn desviou.\nGirou.\nPassou por baixo do braço do garoto.\nE acertou uma rasteira.\nO adversário caiu.\nKewyn ficou parado.\nO professor levantou a mão.\n— Vitória de Kewyn.\nAs crianças comemoraram.\nKewyn sorriu.\nMas o professor não.\nEle estava olhando para os olhos de Kewyn.\nHavia algo diferente naquela linhagem.\nAlgo que ainda estava adormecido.",
  11: "Página 11:\n• O resultado\nNo final do dia, todos os alunos ficaram reunidos.\nO diretor da Academia apareceu.\n— Vocês aprenderam as primeiras lições de um ninja.\nAlguns passaram.\nOutros precisarão treinar mais.\nKewyn estava nervoso.\nAbriely segurava as mãos.\nRodrigo esperava calmamente.\nNicolas não parava de andar de um lado para o outro.\nEntão os nomes começaram a ser chamados.\n— Abriely.\n— Aprovada.\nEla sorriu.\n— Rodrigo.\n— Aprovado.\nRodrigo ajeitou os óculos.\n— Nicolas.\n— Aprovado.\nNicolas levantou os braços.\n— EU CONSEGUI!\nFinalmente:\n— Kewyn.\nSilêncio.\nKewyn olhou para o professor.\n— Aprovado.\nEle sorriu.",
  12: "Página 12:\nNaquele dia, os quatro receberam suas primeiras bandanas.\nEles ainda não eram grandes ninjas.\nAinda não eram Chunin.\nMuito menos Jounin.\nE nenhum deles imaginava o que aconteceria no futuro.\nMas aquele era o começo.\nO começo da história dos quatro jovens que um dia seriam conhecidos como:\nOs Quatro da Ginga.",
  13: "Página 13:\nNaquela noite, Kewyn colocou sua bandana sobre a mesa.\nOlhou para ela durante alguns segundos.\nE fez uma promessa:\n— Um dia... eu vou me tornar forte o suficiente para proteger todo mundo.\nEle não sabia.\nMas o destino já havia começado a se mover.\nE o verdadeiro poder do Clã Ginga estava apenas começando a despertar.\nFim do Capítulo 1.",
  14: "Página 14:\n• Capítulo 2 — Os Quatro Genin\nO dia finalmente havia chegado.\nKewyn, Adriely, Rodrigo e Nicolas não eram mais estudantes da Academia.\nAgora eram Genin.\nPela primeira vez, eles usavam suas bandanas oficialmente como ninjas da Vila da Ginga.\nKewyn caminhava pelas ruas com um sorriso no rosto.\n— Finalmente! — disse ele.\n— Agora começam as missões de verdade!\nNicolas caminhava ao lado dele.\n— Você acha mesmo que vão deixar a gente enfrentar ninjas perigosos logo de cara?\nKewyn colocou as mãos atrás da cabeça.\n— Claro.\nRodrigo, andando alguns passos atrás, ajeitou os óculos.\n— Estatisticamente, não.\nKewyn olhou para ele.\n— Você sempre estraga a diversão.\nAdriely riu.\n— Pelo menos ele está pensando.\n— Eu também penso! — respondeu Kewyn.\nRodrigo olhou para ele.\n— Quando?\nNicolas começou a rir.\n— Essa foi boa!\nKewyn fez uma cara séria.\n— Vocês estão querendo apanhar hoje?\nAdriely entrou no meio dos três.\n— Chega.\nA gente acabou de virar Genin.\nOs quatro continuaram andando.\nNenhum deles sabia que aquele seria o último dia de suas vidas em que seriam apenas crianças brincando de ser ninjas.",
  15: "Página 15:\n• A formação da equipe\nNo mesmo dia, todos os novos Genin foram chamados para a sala principal da Academia.\nO responsável pela formação das equipes entrou.\n— A partir de hoje, vocês trabalharão em grupos de quatro.\nOs alunos ficaram animados.\nKewyn olhou para Nicolas.\n— Tomara que a gente fique junto.\nNicolas respondeu:\n— Se eu ficar com você, vou ter que salvar você toda hora.\n— Você não conseguiria.\n— Quer testar?\nAdriely começou a rir.\nRodrigo apenas observava.\nOs nomes começaram a ser chamados.\nAté que o professor anunciou:\n— Equipe Ginga...\nKewyn, Adriely, Rodrigo e Nicolas.\nOs quatro ficaram em silêncio por um segundo.\nEntão Kewyn abriu um sorriso enorme.\n— A GENTE FICOU JUNTO!\nNicolas levantou o braço.\n— Sabia!\nAdriely sorriu.\nRodrigo ajeitou os óculos.\n— Isso pode funcionar.\nNaquele momento, os quatro se tornaram oficialmente uma equipe.\nMas ainda faltava uma pessoa.\nO líder.",
  16: "Página 16:\n• O mestre\nNo dia seguinte, os quatro estavam sentados na sala esperando seu novo mestre.\nPassaram dez minutos.\nDepois vinte.\nDepois quarenta.\nNicolas estava irritado.\n— Esse cara está atrasado.\nKewyn estava sentado em cima da mesa.\n— Talvez ele tenha medo da gente.\nRodrigo respondeu:\n— Ou talvez esteja testando nossa paciência.\nAdriely olhou para a porta.\n— Acho que ele já está aqui.\nOs três olharam para ela.\n— Como assim?\nAdriely apontou para o teto.\nUma sombra apareceu.\nUm homem estava sentado tranquilamente em cima de uma viga.\n— Finalmente perceberam.\nKewyn levantou rapidamente.\n— Quem é você?!\nO homem pulou no chão.\nEle usava uma roupa tradicional do Clã Ginga, mas com algumas modificações.\nTinha uma faixa escura na cintura e várias marcas de treinamento nos braços.\n— Meu nome é Mestre Jairo.\nKewyn cruzou os braços.\n— Você chegou atrasado.\nJairo sorriu.\n— E você é o garoto que fala demais.\nNicolas começou a rir.\nKewyn olhou para ele.\n— Para de rir.\nJairo colocou as mãos na cintura.\n— Amanhã teremos o primeiro teste.\nRodrigo perguntou:\n— Que teste?\n— Vocês descobrirão.",
  17: "Página 17:\n• O teste da Ginga\nNa manhã seguinte, os quatro chegaram a uma área aberta da floresta.\nJairo colocou quatro pequenos sinos presos à cintura.\nKewyn olhou para eles.\n— É só pegar os sinos?\n— Exatamente.\nNicolas sorriu.\n— Fácil.\nJairo olhou para os quatro.\n— Existe apenas uma regra.\nEle apontou para os sinos.\n— Vocês têm até o meio-dia.\nKewyn perguntou:\n— E se conseguirmos?\nJairo respondeu:\n— Vocês continuam como uma equipe.\nRodrigo percebeu algo.\n— E se não conseguirmos?\nJairo sorriu.\n— Vocês voltarão para a Academia.\nOs quatro ficaram sérios.\nO teste começou.",
  18: "Página 18:\n• Kewyn ataca\nKewyn foi o primeiro.\nEntrou em posição de ginga.\n— Eu vou pegar esse sino.\nEle avançou.\nJairo desapareceu.\nKewyn arregalou os olhos.\n— O quê?!\nJairo apareceu atrás dele.\n— Lento.\nKewyn se virou.\nTentou uma rasteira.\nJairo pulou.\nKewyn girou o corpo e tentou um chute.\nJairo desviou novamente.\n— Você tem talento — disse o mestre.\n— Mas está atacando sem pensar.\nKewyn ficou irritado.\n— Então vou pensar!\nEle recuou.\nDessa vez, começou a observar.",
  19: "Página 19:\n• Adriely entra\nAdriely se aproximou devagar.\nEla não atacou.\nJairo olhou para ela.\n— Você não vai tentar?\n— Ainda não.\nEla colocou as mãos na direção de um pequeno riacho próximo.\nA água começou a se mover.\nJairo percebeu imediatamente.\n— Interessante.\nUma pequena corrente de água se levantou.\nAdriely fez a água circular pelo corpo.\nEntão entrou em ginga.\nA água acompanhava seus movimentos.\nEla tentou prender Jairo usando uma corrente líquida.\nMas ele escapou.\n— Você controla bem o elemento.\nAdriely respirou fundo.\n— Ainda estou aprendendo.\nJairo sorriu.\n— Isso é bom.",
  20: "Página 20:\n• Rodrigo observa\nEnquanto Kewyn e Adriely atacavam, Rodrigo permanecia escondido.\nNicolas perguntou:\n— Você não vai fazer nada?\nRodrigo respondeu:\n— Estou esperando.\n— Esperando o quê?\n— Uma oportunidade.\nRodrigo havia percebido algo.\nJairo estava sempre olhando para quem atacava.\nMas nunca observava os arredores.\nRodrigo começou a analisar o terreno.\nÁrvores.\nPedras.\nSombra.\nDistância.\nDireção do vento.\nEle percebeu que existia um caminho perfeito para chegar por trás do mestre.\n— Agora.\nRodrigo correu.\nJairo virou.\n— Finalmente.\nRodrigo tentou pegar o sino.\nMas Jairo segurou seu braço.\n— Você é inteligente.\nRodrigo sorriu.\n— Eu sei.\n— Mas ainda é previsível.\nJairo o lançou para longe.\nRodrigo caiu no chão.\nSeus óculos quase saíram do rosto.\n— Isso doeu.",
  21: "Página 21:\n• Nicolas e o primeiro raio\nNicolas respirou fundo.\nEle estava determinado.\n— Agora é minha vez.\nComeçou a gingar.\nEsquerda.\nDireita.\nEsquerda.\nDireita.\nSeu chakra começou a circular.\nPequenas faíscas apareceram em suas mãos.\nNicolas olhou para elas.\n— Finalmente...\nJairo percebeu.\n— Raiton?\nNicolas sorriu.\n— Isso mesmo.\nEle concentrou chakra nas pernas.\nUma pequena descarga elétrica percorreu seu corpo.\nEntão ele avançou.\nBUM!\nNicolas desapareceu por um instante e reapareceu diante de Jairo.\nO mestre conseguiu bloquear o golpe.\nMas ficou impressionado.\n— Sua velocidade aumentou.\nNicolas respondeu:\n— E ainda não terminei!\nEle tentou outro ataque.\nJairo desviou.\nNicolas girou no ar.\nSeu pé estava coberto por pequenas faíscas.\n— Ginga Relâmpago!\nO chute passou raspando pelo mestre.\nMas não acertou.\nJairo sorriu.\n— Você ainda precisa aprender a controlar essa velocidade.\nNicolas ficou frustrado.\n— Quase!",
  22: "Página 22:\n• O verdadeiro objetivo\nO tempo passou.\nOs quatro estavam cansados.\nKewyn percebeu que nenhum deles conseguiria pegar o sino sozinho.\nEntão ele teve uma ideia.\n— Pessoal!\nOs outros três olharam.\n— Vamos trabalhar juntos.\nRodrigo ajeitou os óculos.\n— Finalmente você percebeu.\n— Eu tive essa ideia primeiro!\nAdriely sorriu.\n— Qual é o plano?\nKewyn explicou.\nRodrigo analisou.\nNicolas preparou o chakra.\nAdriely ficou perto do riacho.\nOs quatro começaram a se movimentar.\nKewyn foi para frente.\nJairo desviou.\nNicolas apareceu pela lateral.\nJairo bloqueou.\nAdriely levantou uma parede de água.\nJairo precisou mudar de direção.\nFoi exatamente nesse momento que Rodrigo apareceu atrás dele.\nJairo virou.\nMas era uma armadilha.\nKewyn já estava atrás.\n— Agora!\nNicolas disparou.\nAdriely congelou uma pequena parte do chão.\nJairo perdeu o equilíbrio por um instante.\nKewyn entrou em ginga.\nGirou.\nE conseguiu arrancar um dos sinos.\nCLIN!\nO sino caiu na mão de Kewyn.\nTodos ficaram em silêncio.\nJairo olhou para os quatro.\nEntão começou a rir.\n— Vocês entenderam.\nKewyn perguntou:\n— Entendemos o quê?\nJairo respondeu:\n— O teste nunca foi sobre pegar os sinos.\nRodrigo arregalou os olhos.\n— Era sobre trabalho em equipe.\n— Exatamente.",
  23: "Página 23:\n• O começo da equipe\nJairo retirou os outros três sinos.\n— Nenhum de vocês teria conseguido sozinho.\nKewyn olhou para seus companheiros.\nAdriely sorriu.\nRodrigo ajeitou os óculos.\nNicolas levantou o punho.\nJairo continuou:\n— Kewyn tem talento, mas precisa aprender a pensar antes de atacar.\n— Eu sei.\n— Adriely possui um chakra extraordinário, mas ainda não conhece o verdadeiro limite de seu poder.\nEla ficou séria.\n— Eu vou descobrir.\n— Rodrigo possui uma mente capaz de enxergar detalhes que outros ignoram.\nRodrigo sorriu.\n— Obrigado.\nJairo olhou para Nicolas.\n— E você...\nNicolas ficou esperando.\n— Possui uma velocidade perigosa.\nNicolas sorriu.\n— Eu sabia.\n— Mas se não aprender a controlar o Raiton, seu próprio corpo será destruído pelo excesso de chakra.\nO sorriso de Nicolas desapareceu.\n— Eu vou aprender.\nJairo então olhou para os quatro.\n— A partir de hoje, vocês são oficialmente uma equipe.\nKewyn levantou o punho.\n— Equipe Ginga!\nOs quatro colocaram as mãos juntas.\n— Equipe Ginga!",
  24: "Página 24:\n• A primeira missão\nAlguns dias depois, eles receberam sua primeira missão oficial.\nNão era uma missão de combate.\nEra uma missão simples.\nAcompanhar um comerciante até uma vila próxima.\nKewyn ficou decepionado.\n— Só isso?\nJairo respondeu:\n— Todo ninja começa pelas missões simples.\nNicolas perguntou:\n— Quando vamos enfrentar inimigos de verdade?\nJairo sorriu.\n— Quando estiverem preparados.\nOs quatro começaram a caminhar.\nNenhum deles sabia que aquela missão aparentemente simples seria o primeiro passo para uma sequência de acontecimentos que mudaria completamente suas vidas.\nPorque naquela estrada...\nAlguém já estava observando a equipe.\nUma figura escondida entre as árvores observava Kewyn.\nSeus olhos estavam fixos nele.\nEspecialmente em seus olhos castanhos.\n— Então...\nA figura sorriu.\n— O sangue do Clã Ginga ainda existe.\nE desapareceu na floresta.\nContinua...\n\nFim do Capítulo 2.",
  25: "Página 25:\n• Capítulo 3 — A Primeira Missão\nA manhã estava começando quando Kewyn, Adriely, Rodrigo e Nicolas deixaram a Vila da Ginga.\nEra a primeira missão oficial da Equipe Ginga.\nKewyn caminhava na frente, com as mãos atrás da cabeça.\n— Eu ainda acho essa missão muito fácil.\nNicolas caminhava ao lado dele.\n— Eu também.\nA gente deveria estar enfrentando alguém.\nRodrigo ajeitou os óculos.\n— Vocês dois precisam entender que uma missão não precisa envolver combate para ser importante.\nKewyn olhou para trás.\n— Você fala igual ao Mestre Jairo.\n— Talvez porque ele esteja certo.\nAdriely riu.\n— Vocês vão discutir durante a viagem inteira?\n— Não — responderam Kewyn e Nicolas ao mesmo tempo.\nRodrigo suspirou.\n— Eu sabia.\nMais atrás, o Mestre Jairo observava os quatro em silêncio.\nEle parecia tranquilo.\nMas seus olhos estavam atentos a tudo.\nÀ floresta.\nAo caminho.\nE principalmente aos quatro jovens.",
  26: "Página 26:\n• A missão\nO objetivo era simples.\nUm comerciante chamado Senji precisava levar mercadorias até uma pequena vila localizada do outro lado da floresta.\nNão parecia perigoso.\nNão havia relatos de ninjas inimigos.\nNenhum criminoso conhecido estava na região.\nEra exatamente o tipo de missão que um grupo de Genin deveria receber no começo.\nSenji caminhava ao lado de Jairo.\n— Obrigado por aceitarem a missão — disse o comerciante.\nKewyn respondeu:\n— Não precisa agradecer.\nNós somos ninjas!\nSenji sorriu.\n— Eu percebi.\nNicolas perguntou:\n— Tem certeza de que não existe nada perigoso por aqui?\nSenji pensou por alguns segundos.\n— Bem...\nNicolas ficou atento.\n— Bem o quê?\n— Há alguns dias, alguns comerciantes disseram ter visto pessoas estranhas na floresta.\nJairo imediatamente ficou sério.\nKewyn percebeu.\n— Pessoas estranhas?\nSenji balançou a cabeça.\n— Não sei quem eram.\nRodrigo olhou para Jairo.\nO mestre não disse nada.\nMas sua expressão havia mudado.",
  27: "Página 27:\n• A floresta\nDepois de algumas horas de caminhada, a equipe entrou em uma região mais fechada da floresta.\nAs árvores eram enormes.\nA luz do sol quase não chegava ao chão.\nOs sons dos pássaros desapareceram.\nKewyn parou.\n— Está muito quieto.\nAdriely olhou ao redor.\n— Também percebi.\nRodrigo fechou os olhos por alguns segundos.\n— Não estou ouvindo animais.\nNicolas colocou a mão sobre uma kunai.\n— Então tem alguma coisa errada.\nJairo levantou a mão.\nTodos pararam.\n— Ninguém se separa.\nKewyn perguntou:\n— Mestre, você sabe o que está acontecendo?\n— Ainda não.\nJairo olhou para as árvores.\n— Mas estamos sendo observados.\nOs quatro ficaram imóveis.\nKewyn começou a olhar para todos os lados.\n— Onde?\nJairo respondeu:\n— Não sei.\nRodrigo arregalou os olhos.\n— Você também não sabe?\nJairo sorriu.\n— Um bom ninja não precisa saber onde está o inimigo para saber que está sendo observado.",
  28: "Página 28:\n• A emboscada\nUm som veio das árvores.\nTCHAK!\nUma kunai passou perto do rosto de Kewyn.\n— CUIDADO!\nAdriely puxou Kewyn para o lado.\nA kunai acertou uma árvore.\nNicolas imediatamente entrou em posição de combate.\n— Finalmente!\nJairo gritou:\n— Formação!\nOs quatro se posicionaram.\nKewyn na frente.\nAdriely ao lado.\nRodrigo atrás.\nNicolas na lateral.\nTrês homens apareceram entre as árvores.\nEles usavam roupas escuras.\nNão eram ninjas de nenhuma vila conhecida.\nO homem que estava na frente sorriu.\n— Entreguem as mercadorias.\nKewyn deu um passo à frente.\n— E se a gente não entregar?\nO homem riu.\n— Então vamos pegar.\nNicolas sorriu.\n— Agora ficou interessante.\nJairo falou:\n— Não se empolgue.\nO homem avançou.",
  29: "Página 29:\n• A primeira luta de verdade\nKewyn entrou em ginga.\nO inimigo correu diretamente contra ele.\nKewyn desviou para a esquerda.\nO homem tentou acertá-lo novamente.\nKewyn abaixou o corpo.\nUma rasteira.\nO inimigo pulou.\nKewyn girou no chão e tentou acertá-lo com um chute.\nTUM!\nO homem bloqueou.\nKewyn recuou.\n— Ele é forte.\nNicolas apareceu atrás.\n— Então deixa comigo!\nPequenas faíscas começaram a aparecer em seus braços.\nCRACK!\nNicolas disparou.\nO inimigo conseguiu desviar.\nNicolas passou direto.\n— Droga!\nEle freou usando o pé.\n— Minha velocidade ainda está difícil de controlar.\nRodrigo gritou:\n— Nicolas!\nEle está esperando você avançar em linha reta!\nNicolas olhou para ele.\n— Então vou mudar!\nEle começou a gingar.\nEsquerda.\nDireita.\nEsquerda.\nDireita.\nAs faíscas aumentaram.",
  30: "Página 30:\n• A água de Adriely\nEnquanto Nicolas enfrentava um dos inimigos, outro tentou atacar Adriely.\nEla recuou.\nO homem avançou.\nAdriely colocou a mão na direção de uma pequena poça de água.\nA água se levantou.\nO inimigo parou.\n— O quê?\nAdriely movimentou o braço.\nA água se transformou em uma espécie de chicote.\nSHAA!\nO golpe atingiu o chão diante do inimigo.\nEle recuou.\nAdriely entrou em ginga.\nA água acompanhava cada movimento de seu corpo.\nEla girava.\nA água girava.\nEla avançava.\nA água avançava.\nO inimigo tentou agarrá-la.\nAdriely desviou.\nEntão tocou o chão com a mão.\nA água congelou instantaneamente.\nCRAAACK!\nUma camada de gelo surgiu no chão.\nO homem perdeu o equilíbrio.\nAdriely ficou surpresa.\nEla olhou para o próprio chakra.\n— Eu...\nconsegui congelar.\nJairo observou de longe.\nSeus olhos ficaram sérios.\n— Então o gelo começou a despertar...",
  31: "Página 31:\n• Rodrigo percebe\nEnquanto os outros lutavam, Rodrigo percebeu algo estranho.\nOs três inimigos não estavam realmente tentando vencer.\nEles estavam tentando separar a equipe.\nRodrigo observou.\nUm deles atacava Kewyn.\nOutro mantinha Adriely ocupada.\nO terceiro estava evitando Nicolas.\n— Eles estão fazendo isso de propósito.\nRodrigo começou a analisar o terreno.\nEntão percebeu.\n— Mestre Jairo!\n— O quê?\n— Eles não querem as mercadorias.\nJairo olhou para ele.\n— Continue.\n— Se quisessem as mercadorias, já teriam atacado o comerciante.\nJairo ficou em silêncio.\nRodrigo apontou para a floresta.\n— Eles querem alguma outra coisa.\nUm dos inimigos ouviu.\nE seu rosto mudou.\nRodrigo percebeu.\n— Eu estava certo.",
  32: "Página 32:\n• O alvo\nDe repente, um dos homens desapareceu.\nJairo virou imediatamente.\n— Kewyn!\nKewyn olhou para trás.\nO inimigo estava indo diretamente na direção dele.\nKewyn tentou desviar.\nMas o homem conseguiu agarrar seu braço.\n— Peguei você!\nKewyn tentou escapar.\nEntão o homem olhou diretamente para os olhos dele.\nPor um instante...\nEle ficou assustado.\n— Esses olhos...\nKewyn não entendeu.\n— O quê?\nO homem soltou seu braço.\nRecuou.\n— Não pode ser.\nKewyn ficou confuso.\n— O que você está falando?\nO inimigo olhou novamente para os olhos de Kewyn.\n— O herdeiro...",
  33: "Página 33:\nJairo apareceu entre os dois.\nBUM!\nO inimigo foi lançado para longe.\nJairo ficou na frente de Kewyn.\n— Não encoste nele.\nKewyn olhou para o mestre.\n— Mestre...\nJairo não respondeu.\nO inimigo se levantou.\nSeu companheiro gritou:\n— Vamos embora!\nOs três começaram a fugir.\nNicolas ficou indignado.\n— Eles estão fugindo?!\nEle tentou persegui-los.\nJairo segurou seu ombro.\n— Não.\n— Mas podemos pegar eles!\n— Não sabemos quantos existem.\nNicolas parou.\nRodrigo olhou para a floresta.\n— E eles conseguiram o que queriam.\nKewyn perguntou:\n— O quê?\nRodrigo olhou para ele.\n— Ver você.",
  34: "Página 34:\n• O silêncio\nA missão continuou.\nOs inimigos desapareceram completamente.\nSenji estava assustado.\nAdriely ficou olhando para Kewyn.\nNicolas também.\nRodrigo ajeitou os óculos.\nKewyn percebeu.\n— Por que todo mundo está olhando para mim?\nAdriely perguntou:\n— Você conhece aqueles homens?\n— Não.\n— Eles falaram alguma coisa sobre você.\nKewyn ficou pensativo.\n— Eu não entendi.\nJairo interrompeu:\n— Chega.\nTodos olharam para ele.\n— A missão ainda não terminou.\nJairo continuou caminhando.\n— Vamos entregar as mercadorias.\nKewyn ficou parado por alguns segundos.\nEntão correu para alcançar o grupo.\nMas sua cabeça continuava cheia de perguntas.\nPor que aqueles homens ficaram assustados ao olhar para seus olhos?\nE o que significava aquela palavra?\nHerdeiro.",
  35: "Página 35:\n• O retorno\nAo chegarem à vila, Senji agradeceu à equipe.\n— Vocês salvaram minha mercadoria.\nKewyn sorriu.\n— Foi tranquilo.\nNicolas olhou para ele.\n— Tranquilo?\nRodrigo respondeu:\n— Para você, talvez.\nAdriely riu.\nJairo entregou o relatório da missão.\nO responsável pela vila ficou sério ao ler.\n— Vocês encontraram homens desconhecidos?\n— Sim — respondeu Jairo.\n— E eles mencionaram o Clã Ginga?\nJairo ficou em silêncio.\n— Sim.\nO responsável fechou o relatório.\n— Então essa missão não foi tão simples quanto parecia.\nKewyn estava atrás da porta.\nEle ouviu tudo.\nE começou a ficar preocupado.",
  36: "Página 36:\n• A noite\nNaquela noite, Kewyn não conseguiu dormir.\nEle saiu de casa e caminhou até o campo de treinamento.\nA lua iluminava a vila.\nKewyn ficou diante de um lago.\nOlhou para o próprio reflexo.\nSeus dois olhos continuavam normais.\nCastanhos.\nSem Byakugan.\nSem qualquer poder especial aparente.\nEle tocou o próprio rosto.\n— O que tem de tão especial nos meus olhos?\nDe repente...\nUma pequena dor surgiu atrás de seu olho esquerdo.\nKewyn fechou os olhos.\n— Ai...\nA dor desapareceu.\nEle abriu os olhos novamente.\nTudo estava normal.\nKewyn respirou fundo.\n— Deve ser só cansaço.",
  37: "Página 37:\nEle não sabia.\nMas naquela mesma noite, muito longe dali...\nA pessoa que havia observado a equipe estava diante de uma fogueira.\nUm homem mais velho estava sentado à sua frente.\n— Você encontrou o garoto?\nA figura respondeu:\n— Sim.\n— E?\n— Ele ainda não despertou.\nO homem ficou em silêncio.\n— Então temos tempo.\nA figura sorriu.\n— Quanto tempo?\nO homem levantou os olhos.\n— Até o primeiro sinal do Byakugan.\nA fogueira estalou.\nCREC.\nE, naquele momento, o destino de Kewyn começou a mudar.\nPorque seu poder ainda estava adormecido.\nMas não ficaria assim para sempre.\nContinua...\n\nFim do Capítulo 3.",
  38: "Página 38:\n• Capítulo 4 — A Primeira Tempestade\nA manhã havia chegado silenciosa à Vila da Ginga.\nDepois da primeira missão como Genin, Kewyn, Adriely, Rodrigo e Nicolas estavam começando a entender o que significava fazer parte de uma verdadeira equipe.\nEles ainda eram jovens.\nAinda cometiam erros.\nAinda discutiam por coisas pequenas.\nMas alguma coisa havia mudado.\nEles já não treinavam apenas como quatro crianças.\nAgora treinavam como ninjas.\nE o Mestre Jairo sabia que estava na hora de testar até onde eles realmente poderiam chegar.",
  39: "Página 39:\n• A notícia\nKewyn estava no campo de treinamento, praticando sua ginga.\nEsquerda.\nDireita.\nEsquerda.\nGiro.\nChute.\nEle repetia o movimento várias vezes.\n— Mais uma vez! — gritou Nicolas.\nKewyn olhou para ele.\n— Você está me desafiando?\n— Estou.\n— Então vem.\nNicolas sorriu.\nOs dois começaram a lutar.\nNicolas avançava rapidamente, enquanto Kewyn usava a ginga para escapar dos ataques.\n— Você está ficando mais rápido! — disse Kewyn.\n— Eu sei!\nPequenas faíscas apareceram nos pés de Nicolas.\nKewyn arregalou os olhos.\n— Você está usando Raiton de novo?\n— Só um pouquinho.\nNicolas avançou.\nKewyn desviou por pouco.\n— Ei!\nVocê quase me acertou!\n— Esse era o objetivo!\nOs dois continuaram.\nMais afastada, Adriely observava enquanto treinava seu controle sobre a água.\nUma pequena esfera líquida flutuava diante de suas mãos.\nRodrigo estava sentado em uma pedra, lendo.\nEntão...\n— Vocês quatro.\nA voz de Jairo fez todos pararem.\nO mestre estava parado atrás deles.\n— Temos uma missão.\nNicolas imediatamente ficou animado.\n— Finalmente uma missão de verdade?!\nJairo cruzou os braços.\n— Talvez.\nKewyn se aproximou.\n— Qual é?\nJairo entregou um pergaminho.\n— Uma pequena vila ao norte perdeu contato com alguns comerciantes.\nPrecisamos descobrir o motivo.\nRodrigo pegou o pergaminho.\n— Perdeu contato?\n— Sim.\n— Isso não parece uma missão simples.\nJairo sorriu.\n— Não é.",
  40: "Página 40:\n• A estrada do norte\nHoras depois, os cinco deixaram a Vila da Ginga.\nA floresta era densa.\nÁrvores enormes cobriam o céu.\nO caminho ficava cada vez mais estreito.\nKewyn caminhava na frente.\n— Eu não estou sentindo nada.\nRodrigo respondeu:\n— Esse é justamente o problema.\nKewyn olhou para trás.\n— O que você quer dizer?\nRodrigo ajeitou os óculos.\n— Se alguém estivesse nos observando, você provavelmente não perceberia.\nKewyn ficou sério.\n— Está dizendo que tem alguém aqui?\n— Não.\nRodrigo apontou para as árvores.\n— Estou dizendo que não podemos ter certeza.\nAdriely olhou para os lados.\n— Então vamos ficar atentos.\nNicolas colocou a mão perto da cintura.\n— Se aparecer alguém, eu resolvo.\nJairo, que caminhava atrás deles, falou:\n— Não.\nNicolas olhou para trás.\n— Não?\n— Você não vai atacar ninguém sem saber quem é.\nNicolas fez uma expressão contrariada.\n— Mas...\n— Um ninja que ataca sem pensar pode colocar toda a equipe em perigo.\nKewyn olhou para Nicolas.\n— Ele tem razão.\nNicolas cruzou os braços.\n— Você também fazia isso.\nKewyn ficou em silêncio.\n— ...É verdade.\nAdriely começou a rir.",
  41: "Página 41:\n• A vila abandonada\nDepois de algumas horas, chegaram à vila.\nO lugar estava completamente silencioso.\nNenhuma pessoa nas ruas.\nNenhum comerciante.\nNenhuma criança brincando.\nNenhum som.\nKewyn olhou ao redor.\n— Isso está estranho.\nJairo fez um sinal para que todos parassem.\n— Formação.\nOs quatro se posicionaram.\nRodrigo ficou atrás.\nAdriely à esquerda.\nNicolas à direita.\nKewyn na frente.\nJairo permaneceu no centro.\n— Não baixem a guarda.\nEles avançaram lentamente.\nEntão encontraram as primeiras marcas.\nUma carroça destruída.\nCaixas espalhadas.\nMarcas de luta no chão.\nKewyn se agachou.\n— Houve uma batalha aqui.\nRodrigo observou as marcas.\n— Três pessoas.\nAdriely perguntou:\n— Como sabe?\n— Pegadas.\nEle apontou.\n— Uma pessoa era mais pesada.\nOutra estava correndo.\nE a terceira...\nRodrigo parou.\n— O quê?\n— Não deixou pegadas.\nJairo ficou sério.\n— Todos para trás.\nTarde demais.\nUma kunai passou voando entre Kewyn e Nicolas.\nCLANG!\nJairo desviou a arma.\n— Ataque!\nQuatro figuras apareceram no alto das árvores.\nNicolas sorriu.\n— Finalmente!\nJairo gritou:\n— Não se separem!\nOs inimigos saltaram.",
  42: "Página 42:\n• A batalha começa\nKewyn entrou imediatamente em ginga.\nUm dos inimigos avançou com uma espada.\nKewyn desviou.\nA lâmina passou perto de seu rosto.\nEle colocou uma mão no chão e girou as pernas.\nRasteira da Ginga!\nO inimigo caiu.\nKewyn se levantou.\n— Um!\nOutro adversário veio por trás.\n— Kewyn!\nAdriely percebeu.\nEla levantou as mãos.\nA água de um pequeno riacho próximo começou a subir.\nJutsu da Ginga: Corrente Circular!\nA água atingiu o inimigo e o empurrou para longe.\nKewyn olhou para ela.\n— Valeu!\nAdriely sorriu.\n— Não se distraia!",
  43: "Página 43:\n• Rodrigo contra dois\nRodrigo estava cercado.\nDois inimigos avançaram ao mesmo tempo.\nEle recuou.\nUm soco.\nDesviou.\nOutro golpe.\nAbaixou.\nRodrigo começou a gingar.\nOs dois inimigos ficaram confusos.\n— O que ele está fazendo?\nRodrigo respondeu:\n— Observando.\nEle percebeu que os dois atacavam juntos.\nSempre que o primeiro atacava pela esquerda, o segundo vinha pela direita.\nRodrigo esperou.\nUm.\nDois.\nTrês.\nAgora.\nEle desviou do primeiro e fez o segundo acertar o próprio companheiro.\n— Funcionou.\nRodrigo ajeitou os óculos.\n— Exatamente como imaginei.",
  44: "Página 44:\n• Nicolas libera o raio\nDo outro lado, Nicolas enfrentava um inimigo muito mais rápido.\nNicolas avançava.\nO adversário desviava.\nNicolas atacava novamente.\nNada.\n— Para de fugir!\nO inimigo sorriu.\n— Você é rápido.\nNicolas apertou os punhos.\n— Ainda não viu nada.\nO chakra começou a percorrer seu corpo.\nFaíscas surgiram.\nDepois mais.\nE mais.\nCRACK!\nUm brilho de eletricidade percorreu seus braços.\nNicolas avançou.\nGinga Raiton!\nSeu corpo se moveu numa velocidade muito maior.\nO inimigo tentou bloquear.\nNicolas passou por ele.\nGirou.\nE acertou um chute.\nO adversário foi lançado contra uma árvore.\nNicolas ficou parado.\nRespirando pesado.\n— Eu consegui...\nMas Jairo gritou:\n— Nicolas!\nControle o chakra!\nNicolas olhou para as próprias mãos.\nAs faíscas estavam aumentando.\n— Eu não consigo parar!\nJairo correu até ele.\n— Respire!\nNicolas fechou os olhos.\nInspirou.\nExpirou.\nAs faíscas diminuíram.\nJairo colocou a mão em seu ombro.\n— Seu Raiton é poderoso.\nNicolas olhou para ele.\n— Então eu posso ficar ainda mais forte?\nJairo respondeu:\n— Pode.\nE ficou sério.\n— Mas primeiro precisa aprender a não ser destruído pelo próprio poder.",
  45: "Página 45:\n• O inimigo escondido\nA batalha parecia estar terminando.\nOs quatro inimigos estavam derrotados.\nKewyn respirou aliviado.\n— Acabou?\nRodrigo olhou para as árvores.\n— Não.\nKewyn ficou sério.\n— De novo?\nRodrigo apontou.\n— Tem alguém observando.\nJairo percebeu no mesmo instante.\n— Todos para trás!\nUma presença surgiu no alto de uma árvore.\nUm homem usando uma máscara escura.\nEle não atacou.\nApenas olhou para Kewyn.\nMais precisamente...\nPara os olhos de Kewyn.\nKewyn sentiu um arrepio.\n— Quem é você?\nO homem não respondeu.\nEle simplesmente disse:\n— Então você é o garoto.\nKewyn fechou os punhos.\n— Que garoto?\nO homem sorriu.\n— O último herdeiro.\nJairo ficou imediatamente sério.\n— Não diga mais nada.\nO homem olhou para Jairo.\n— Você sabe do que estou falando.\nKewyn ficou confuso.\n— Mestre?\nJairo não respondeu.\nO homem fez alguns selos.\n— Nós vamos nos encontrar novamente.\nUma fumaça tomou conta da área.\nQuando desapareceu...\nEle havia sumido.",
  46: "Página 46:\n• O segredo de Jairo\nA equipe ficou em silêncio.\nKewyn virou-se para Jairo.\n— Mestre.\n— Sim?\n— O que ele quis dizer?\nJairo ficou alguns segundos sem responder.\n— Nada.\nKewyn franziu a testa.\n— Não foi nada.\n— Kewyn...\n— Ele falou de mim.\nAdriely percebeu que Jairo estava escondendo alguma coisa.\nRodrigo também.\nNicolas perguntou:\n— Mestre, quem era aquele cara?\nJairo olhou para os quatro.\n— Ainda não é hora de vocês saberem.\nKewyn ficou irritado.\n— Por quê?\n— Porque vocês ainda são Genin.\nKewyn respondeu:\n— E quando vamos deixar de ser?\nJairo sorriu.\n— Quando estiverem preparados para descobrir coisas que talvez preferissem nunca saber.\nKewyn ficou em silêncio.",
  47: "Página 47:\n• O retorno\nA missão terminou.\nA vila estava segura.\nOs comerciantes foram encontrados escondidos em uma casa subterrânea.\nNenhum deles sabia quem eram os homens que haviam atacado.\nQuando a equipe voltou para a Vila da Ginga, todos comemoraram.\nPara a vila, aquela havia sido uma missão bem-sucedida.\nMas para Kewyn...\nEra diferente.\nNaquela noite, ele estava sentado sozinho no telhado de sua casa.\nOlhou para o céu.\nSeus olhos continuavam completamente normais.\nCastanhos.\nSem nenhuma marca.\nSem nenhum sinal do poder que existia dentro de sua linhagem.\nEle tocou o próprio rosto.\n— Último herdeiro...\nAquelas palavras não saíam de sua cabeça.\nEntão ouviu uma voz atrás dele.\n— Você não consegue dormir?\nKewyn virou.\nEra Jairo.\n— Mestre...\nJairo sentou ao lado dele.\nPor alguns segundos, os dois ficaram em silêncio.\nEntão Kewyn perguntou:\n— Tem alguma coisa errada comigo?\nJairo olhou para ele.\n— Não.\n— Então por que aquele homem me chamou de herdeiro?\nJairo respirou fundo.\n— Porque existe uma história sobre sua família que você ainda não conhece.\nKewyn ficou sério.\n— Que história?\nJairo se levantou.\n— Quando chegar a hora, você vai descobrir.\nEle começou a ir embora.\nKewyn gritou:\n— E quando vai chegar essa hora?!\nJairo parou.\nSem olhar para trás, respondeu:\n— Quando seus olhos estiverem prontos para enxergar.\nKewyn ficou parado.\nSem entender.\nSem saber que aquelas palavras seriam importantes no futuro.\nMuito importantes.",
  48: "Página 48:\nEm outro lugar...\nLonge da Vila da Ginga, o homem mascarado caminhava por uma floresta escura.\nOutro homem apareceu.\n— Você encontrou o garoto?\nO mascarado respondeu:\n— Sim.\n— E?\nEle sorriu.\n— O poder ainda está adormecido.\n— Então por que não o matou?\nO mascarado ficou em silêncio.\n— Porque eu quero ver até onde ele consegue chegar.\nO outro homem perguntou:\n— E quando ele despertar?\nO mascarado olhou para a lua.\n— Então teremos nosso verdadeiro inimigo.\nNa Vila da Ginga, Kewyn finalmente fechou os olhos.\nEle ainda era apenas um Genin.\nAinda não possuía o Byakugan.\nAinda não conhecia o verdadeiro poder de sua família.\nMas alguma coisa havia começado.\nUma história antiga estava voltando.\nE, dentro dos olhos castanhos de um garoto de apenas oito anos...\num poder ancestral esperava pelo momento certo para despertar.\nContinua...\n\nFim do Capítulo 4 — A Primeira Tempestade.",
  49: "Página 49:\n• Capítulo 5 — O Despertar\nDepois da missão na vila abandonada, os quatro Genin voltaram ao treinamento.\nMas Kewyn não conseguia esquecer as palavras daquele homem.\n\"O último herdeiro.\"\nE, principalmente, as palavras de Jairo:\n\"Quando seus olhos estiverem prontos para enxergar.\"\nKewyn queria respostas.\nMas, quanto mais perguntava, mais o mestre evitava o assunto.",
  50: "Página 50:\n• Um novo treinamento\nNa manhã seguinte, os quatro chegaram ao campo de treinamento.\nJairo já estava esperando.\n— Hoje será diferente — disse o mestre.\nNicolas sorriu.\n— Vamos aprender uma técnica nova?\n— Não.\nAdriely perguntou:\n— Então o que vamos fazer?\nJairo apontou para uma enorme área de areia.\n— Hoje vocês vão aprender a lutar sem depender de nenhuma técnica especial.\nKewyn ficou confuso.\n— Mas eu uso minha ginga.\n— E continuará usando.\nJairo olhou para os quatro.\n— Mas quero descobrir quem vocês são quando ficam sem chakra.\nRodrigo ajeitou os óculos.\n— Um teste de resistência.\n— Exatamente.",
  51: "Página 51:\n• Kewyn contra Nicolas\nA primeira luta foi entre Kewyn e Nicolas.\nOs dois ficaram frente a frente.\nNicolas começou a sorrir.\n— Dessa vez eu vou ganhar.\nKewyn entrou na ginga.\n— Você fala isso toda vez.\n— Porque um dia vai acontecer.\nJairo levantou a mão.\n— Comecem!\nNicolas avançou.\nKewyn desviou.\nUm chute passou pelo seu rosto.\nKewyn girou e tentou uma rasteira.\nNicolas pulou.\n— Quase!\n— Você está ficando melhor.\nNicolas avançou novamente.\nKewyn recuou.\nOs dois começaram a trocar golpes cada vez mais rápidos.\nMas havia uma diferença.\nNicolas estava aprendendo a controlar sua velocidade.\nAntes, ele atacava sem pensar.\nAgora, esperava o momento certo.\nKewyn percebeu.\n— Você mudou.\nNicolas sorriu.\n— Eu treinei.\nEntão Nicolas avançou.\nKewyn tentou desviar.\nMas Nicolas mudou a direção no último instante.\nTHUMP!\nO golpe acertou Kewyn no ombro.\nKewyn caiu de joelhos.\nNicolas levantou os braços.\n— EU GANHEI!\nKewyn ficou olhando para ele.\nDepois começou a rir.\n— Tá bom.\nDessa vez você ganhou.\nJairo observou em silêncio.\nOs dois estavam evoluindo.",
  52: "Página 52:\n• Adriely e o rio\nEnquanto os garotos treinavam, Adriely estava perto do rio.\nEla fechou os olhos.\nRespirou profundamente.\nA água começou a se mover.\nPrimeiro, uma pequena onda.\nDepois outra.\nEla levantou a mão.\nA água começou a subir.\nUm enorme arco líquido apareceu acima dela.\nAdriely abriu os olhos.\n— Mais.\nEla aumentou a quantidade de chakra.\nA água subiu ainda mais.\nEntão...\nCRACK!\nUma parte da água começou a congelar.\nAdriely arregalou os olhos.\n— Gelo?\nEla não tinha tentado fazer aquilo.\nA superfície da água ficou coberta por uma fina camada congelada.\nAdriely tocou nela.\n— Eu consegui...\nJairo apareceu atrás dela.\n— Não.\nAdriely se virou.\n— Não?\n— Você não conseguiu.\nEle apontou para o rio.\n— Seu chakra fez isso sozinho.\nAdriely ficou surpresa.\n— Então...\n— Existe alguma coisa dentro do seu chakra que você ainda não entende.\nAdriely olhou para as próprias mãos.\n— Eu posso controlar água e gelo?\nJairo respondeu:\n— Talvez.\n— \"Talvez\"?\n— Ainda é cedo para saber qual é o verdadeiro limite do seu poder.\nAdriely sorriu.\n— Então vou descobrir.",
  53: "Página 53:\n• Rodrigo e o vento\nRodrigo também começou a treinar sua própria habilidade.\nEle segurava uma folha entre os dedos.\n— Chakra de vento...\nEle concentrou energia.\nA folha se moveu.\nRodrigo tentou novamente.\nNada.\nEle respirou.\nTentou mais uma vez.\nFWOOSH!\nUma pequena rajada de vento atravessou o campo.\nRodrigo sorriu.\n— Finalmente.\nJairo observou.\n— Seu controle é preciso.\nRodrigo respondeu:\n— Eu prefiro precisão à força.\n— Então transforme essa precisão em uma técnica.\nRodrigo começou a pensar.\nEle fez movimentos semelhantes aos da capoeira.\nGirou o corpo.\nAbaixou.\nColocou uma mão no chão.\nO vento acompanhou o movimento.\nUma pequena lâmina de ar passou pela grama.\nRodrigo arregalou os olhos.\n— Eu posso usar a ginga para controlar o vento.\nJairo sorriu.\n— Agora você está começando a entender.",
  54: "Página 54:\n• Nicolas e o Raiton\nNicolas estava treinando sozinho.\nFaíscas percorriam seus braços.\n— Mais rápido...\nEle tentou acelerar.\nCRACK!\nUma descarga percorreu seu corpo.\nNicolas caiu de joelhos.\n— Agh!\nJairo apareceu imediatamente.\n— Pare.\n— Eu consigo.\n— Nicolas.\n— Eu consigo!\nNicolas tentou novamente.\nMais eletricidade.\nMais velocidade.\nMais dor.\nJairo segurou seu braço.\n— Você está tentando dominar o raio usando força.\nNicolas respirava pesado.\n— E como eu faço?\n— Não domine.\nNicolas ficou confuso.\n— O quê?\n— Aprenda a acompanhar.\nJairo soltou seu braço.\n— O raio não precisa obedecer você.\nSeu corpo precisa aprender a se mover junto dele.\nNicolas ficou pensando.\nEntão sorriu.\n— Entendi.\nEle entrou na ginga.\nEsquerda.\nDireita.\nEsquerda.\nO chakra começou a circular.\nDessa vez, as faíscas não explodiram.\nElas acompanharam seus movimentos.\nJairo assentiu.\n— Melhor.\nNicolas sorriu.\n— Eu vou ser o ninja mais rápido da Vila da Ginga.",
  55: "Página 55:\n• O segredo de Kewyn\nNo final do treinamento, os quatro estavam juntos.\nKewyn permanecia quieto.\nAdriely percebeu.\n— O que foi?\n— Nada.\nRodrigo olhou para ele.\n— É sobre aquele homem.\nKewyn ficou surpreso.\n— Como você sabe?\nRodrigo ajeitou os óculos.\n— Você está pensando nele desde que voltamos.\nNicolas perguntou:\n— Que homem?\nKewyn ficou em silêncio.\nEntão contou tudo.\nO homem mascarado.\nAs palavras sobre seu sangue.\nO segredo que Jairo parecia esconder.\nNicolas ficou sério.\n— Você acha que sua família tem alguma coisa especial?\nKewyn olhou para o chão.\n— Não sei.\nAdriely colocou a mão em seu ombro.\n— Seja o que for, você não está sozinho.\nKewyn sorriu.\n— Obrigado.\nRodrigo completou:\n— E quando descobrirmos, descobriremos juntos.\nNicolas levantou o punho.\n— Equipe Ginga!\nOs quatro encostaram os punhos.\n— Equipe Ginga!",
  56: "Página 56:\n• O incidente\nNaquela mesma tarde, a equipe recebeu uma nova missão.\nDessa vez, precisavam proteger uma pequena caravana que atravessaria uma região montanhosa.\nA missão parecia simples.\nMas, quando chegaram ao local...\nJairo parou.\n— Alguma coisa está errada.\nKewyn olhou ao redor.\n— O quê?\nJairo fechou os olhos.\n— Chakra.\nRodrigo percebeu primeiro.\n— Tem alguém escondido.\nEntão uma explosão aconteceu.\nBOOOOM!\nA estrada foi destruída.\nAs pedras começaram a cair.\n— CORRAM! — gritou Jairo.\nKewyn segurou Adriely pelo braço.\nNicolas correu para o outro lado.\nRodrigo tentou proteger os civis.\nUma enorme pedra caiu na direção de uma criança.\nKewyn viu.\nSem pensar, correu.\n— SAI DAÍ!\nEle empurrou a criança.\nA pedra caiu.\nCRASH!\nKewyn desapareceu atrás da nuvem de poeira.\n— KEWYN! — gritou Adriely.\nNicolas correu até lá.\n— Kewyn!\nNada.",
  57: "Página 57:\nEntão...\nUma pedra se moveu.\nKewyn apareceu.\nEstava ferido.\nMas estava de pé.\n— Estou bem.\nAdriely respirou aliviada.\nMas Jairo estava olhando para ele.\nSeus olhos estavam diferentes.\nPor apenas um instante.\nUma pequena veia apareceu perto de um dos olhos de Kewyn.\nJairo arregalou os olhos.\n— Não...\nKewyn piscou.\nA marca desapareceu.\n— Mestre?\nJairo ficou em silêncio.",
  58: "Página 58:\n• O primeiro sinal\nNaquela noite, depois da missão, Kewyn estava sozinho.\nEle estava sentado perto do rio.\nLavou o rosto.\nOlhou para seu reflexo na água.\nSeus olhos continuavam castanhos.\nNormais.\nMas então...\nPor um instante...\nA visão mudou.\nKewyn conseguiu enxergar através das árvores.\nConseguiu ver o fluxo de chakra de um animal escondido na floresta.\nEle piscou.\nTudo voltou ao normal.\nKewyn ficou parado.\n— O que foi isso?\nAtrás dele, Jairo observava.\nO mestre fechou os olhos.\n— Finalmente começou.",
  59: "Página 59:\n• O despertar\nJairo caminhou até Kewyn.\n— Kewyn.\n— Mestre...\n— Não conte a ninguém ainda.\nKewyn se virou.\n— O que aconteceu comigo?\nJairo olhou diretamente para seus olhos.\n— Seu Byakugan começou a despertar.\nKewyn ficou completamente imóvel.\n— Meu...\no quê?\nJairo respirou fundo.\n— O poder que pertence ao seu sangue.\nKewyn tocou os próprios olhos.\n— Mas eu não sou do clã que possui esse poder.\nJairo respondeu:\n— Você é do Clã Ginga.\n— Então como eu tenho isso?\nJairo ficou em silêncio.\n— Essa é uma história que você ainda precisa descobrir.\nKewyn apertou os punhos.\n— Eu quero saber agora.\n— Ainda não.\n— Por quê?!\nJairo respondeu calmamente:\n— Porque despertar um poder é fácil.\nEle olhou para Kewyn.\n— Difícil é aprender a viver com ele.\nKewyn ficou em silêncio.",
  60: "Página 60:\nEntão olhou novamente para o rio.\nSeu reflexo continuava normal.\nMas agora ele sabia.\nDentro dele havia algo diferente.\nAlgo antigo.\nAlgo que estava apenas começando a despertar.\nE, em algum lugar distante...\no homem mascarado abriu um sorriso.\n— Então finalmente começou.\nContinua...\n\nFim do Capítulo 5 — O Despertar.",
  61: "Página 61:\n• Capítulo 6 — Os Olhos da Ginga\nNaquela noite, Kewyn não conseguiu dormir.\nAs palavras de Jairo continuavam passando pela sua cabeça.\n\"Seu Byakugan começou a despertar.\"\nByakugan.\nUm poder que ele nunca imaginou possuir.\nKewyn se levantou da cama e foi até o espelho.\nOlhou para os próprios olhos.\nCastanhos.\nNormais.\n— Então é verdade...\nEle tocou o rosto.\n— Tem alguma coisa dentro de mim.\nKewyn fechou os olhos.\nTentou sentir o chakra.\nNada.\nAbriu novamente.\nTudo continuava normal.\n— Como eu faço isso acontecer?\nEle não sabia.\nMas decidiu descobrir.",
  62: "Página 62:\n• O treinamento secreto\nNa manhã seguinte, Kewyn chegou ao campo de treinamento antes dos outros.\nJairo já estava lá.\n— Você veio cedo.\nKewyn cruzou os braços.\n— Quero aprender a controlar o Byakugan.\nJairo ficou em silêncio.\n— Você ainda não consegue ativá-lo quando quer.\n— Então me ensina.\n— Não é tão simples.\nKewyn insistiu:\n— Eu preciso aprender.\nJairo olhou para ele.\n— Tudo bem.\nO mestre colocou uma pedra no chão.\n— Sente-se.\nKewyn sentou.\n— Feche os olhos.\nEle obedeceu.\n— Agora, não tente enxergar.\nKewyn franziu a testa.\n— Como assim?\n— O Byakugan não é apenas uma forma diferente de enxergar.\nVocê precisa aprender a perceber o chakra antes de tentar vê-lo.\nKewyn respirou fundo.\nSilêncio.\nEle tentou sentir.\nNada.\nMinutos passaram.\n— Não consigo.\n— Continue.\nMais alguns minutos.\nKewyn começou a ficar frustrado.\n— Eu não estou sentindo nada!\n— Então pare de procurar.\nKewyn abriu os olhos.\n— O quê?\nJairo sorriu.\n— Você está tentando encontrar o chakra.\nEm vez disso, deixe o chakra encontrar você.",
  63: "Página 63:\nKewyn ficou pensando.\nFechou os olhos novamente.\nRespirou.\nDessa vez, não tentou forçar.\nApenas ficou parado.\nEntão...\ntum.\nEle sentiu alguma coisa.\nUm fluxo.\nFraco.\nDistante.\nKewyn abriu os olhos.\n— Eu senti.\nJairo assentiu.\n— De novo.\nKewyn fechou os olhos.\nDessa vez, conseguiu sentir o chakra de Jairo.\nDepois o de um pássaro.\nDepois o de pequenos animais na floresta.\n— Estou conseguindo!\n— Ainda não acabou.\nKewyn sorriu.\n— Eu sei.",
  64: "Página 64:\n• A equipe descobre\nMais tarde, Adriely, Rodrigo e Nicolas chegaram ao campo.\nNicolas percebeu imediatamente que havia alguma coisa diferente.\n— Você está treinando sozinho?\nKewyn respondeu:\n— Estou.\nRodrigo ajeitou os óculos.\n— Por quê?\nKewyn olhou para Jairo.\nO mestre fez um pequeno sinal com a cabeça.\nKewyn respirou fundo.\n— Eu preciso contar uma coisa para vocês.\nOs três ficaram atentos.\n— Na missão passada...\nalguma coisa aconteceu comigo.\nAdriely perguntou:\n— O quê?\nKewyn respondeu:\n— Meu Byakugan despertou.\nSilêncio.\nNicolas arregalou os olhos.\n— Você tem um Byakugan?!\nKewyn assentiu.\nRodrigo ficou pensativo.\n— Isso explica aquela alteração nos seus olhos.\nAdriely sorriu.\n— Então você finalmente descobriu o que estava escondendo dentro de você.\nKewyn ficou surpreso.\n— Você não está assustada?\n— Por quê?\n— Porque é um poder que eu nem conheço.\nAdriely respondeu:\n— É justamente por isso que vamos aprender juntos.\nNicolas levantou o punho.\n— E quando você aprender, quero lutar contra você.\nKewyn riu.\n— Você nunca desiste, né?\n— Nunca!\nRodrigo completou:\n— Só espero que você não fique convencido.\nKewyn colocou as mãos atrás da cabeça.\n— Eu?\nConvencido?\nOs três começaram a rir.\nJairo observava de longe.\nEle sabia que aquilo era importante.\nKewyn tinha acabou de revelar seu maior segredo.\nE seus amigos não haviam se afastado.\nPelo contrário.\nA equipe estava ficando ainda mais unida.",
  65: "Página 65:\n• O primeiro Byakugan\nJairo decidiu testar Kewyn.\n— Muito bem.\nTodos ficaram em posição.\n— Kewyn, tente ativar o Byakugan.\nEle respirou.\nFechou os olhos.\nConcentrou o chakra.\nNada aconteceu.\nNicolas perguntou:\n— Não funcionou?\n— Ainda não.\nKewyn tentou novamente.\nSeu chakra começou a circular pelo corpo.\nAs veias próximas aos olhos começaram a aparecer.\nByakugan!\nPor um instante, seus olhos ficaram completamente claros.\nKewyn arregalou os olhos.\nO mundo mudou.\nEle conseguia enxergar através das árvores.\nConseguiu ver o chakra circulando dentro de Jairo.\nConseguiu enxergar os pontos de chakra dos próprios companheiros.\n— Eu consigo ver...\nAdriely perguntou:\n— O quê?\n— Tudo.\nKewyn olhou para Nicolas.\n— Consigo ver seu chakra.\nNicolas ficou impressionado.\n— Sério?\nKewyn olhou para Rodrigo.\n— E o seu também.\nDepois olhou para Adriely.\nMas algo chamou sua atenção.\nO chakra de Adriely era diferente.\nMuito mais intenso quando ela estava perto da água.\nKewyn ficou impressionado.\n— Adriely...\n— O quê?\n— Seu chakra está reagindo à água.\nEla olhou para o rio.\nA água começou a se movimentar sozinha.",
  66: "Página 66:\nJairo ficou sério.\n— Desligue o Byakugan.\nKewyn tentou.\nMas não conseguiu.\n— Eu não consigo!\nJairo avançou.\n— Kewyn, respire!\nKewyn começou a sentir dor.\n— Está queimando!\nJairo segurou seus ombros.\n— Não lute contra o poder!\nKewyn fechou os olhos.\nRespirou profundamente.\nE o Byakugan desapareceu.\nEle caiu de joelhos.\nAdriely correu até ele.\n— Você está bem?\nKewyn respirou fundo.\n— Estou.\nJairo olhou para ele.\n— Esse é o perigo.\nKewyn levantou a cabeça.\n— Que perigo?\n— Quanto mais você enxergar, mais chakra será necessário para manter o Byakugan ativo.\nRodrigo entendeu.\n— Então, se ele usar por muito tempo...\n— Vai esgotar o próprio corpo.\nKewyn ficou sério.\n— Então eu preciso aprender rápido.",
  67: "Página 67:\n• A nova técnica\nJairo decidiu ensinar Kewyn uma técnica diferente.\nNão era uma técnica de Byakugan tradicional.\nEra uma técnica criada pelo próprio Clã Ginga.\nGinga dos Cem Olhares.\nJairo explicou:\n— O Byakugan permite que você veja os movimentos do adversário antes que eles aconteçam.\nKewyn entrou em posição.\n— Então posso usar isso para lutar com a ginga.\n— Exatamente.\nKewyn começou a se movimentar.\nEsquerda.\nDireita.\nGiro.\nBaixo.\nAlto.\nSeus olhos acompanhavam cada movimento.\nJairo atacou.\nKewyn desviou antes mesmo do golpe chegar.\nJairo atacou novamente.\nKewyn girou.\nOutro golpe.\nKewyn abaixou.\n— Eu consigo prever!\nJairo sorriu.\n— Não está prevendo.\nKewyn ficou confuso.\n— Então o que estou fazendo?\n— Está enxergando.\nKewyn sorriu.\n— É ainda melhor.",
  68: "Página 68:\n• Uma nova missão\nPoucos dias depois, uma nova missão chegou.\nDessa vez, não era uma missão simples.\nUm grupo de ninjas havia sido visto próximo às fronteiras da Vila da Ginga.\nJairo recebeu a ordem de investigar.\nKewyn, Adriely, Rodrigo e Nicolas iriam junto.\nAntes de partir, Jairo falou:\n— Essa missão é diferente das anteriores.\nNicolas perguntou:\n— Mais perigosa?\n— Sim.\nRodrigo ficou sério.\n— São os mesmos homens da missão anterior?\nJairo respondeu:\n— Ainda não sabemos.\nKewyn apertou sua bandana.\nDesde que havia descoberto o Byakugan, alguma coisa dentro dele havia mudado.\nEle queria respostas.\nE talvez aquela missão trouxesse algumas.",
  69: "Página 69:\n• A floresta escura\nA equipe avançou pela floresta.\nKewyn ativou o Byakugan por alguns segundos.\n— Esperem.\nTodos pararam.\nJairo perguntou:\n— O que você viu?\nKewyn apontou para frente.\n— Três pessoas.\nRodrigo perguntou:\n— Distância?\n— Aproximadamente duzentos metros.\nJairo ficou surpreso.\n— Você consegue enxergar tão longe?\nKewyn sorriu.\n— Acho que sim.\nJairo respondeu:\n— Não se empolgue.\nKewyn desativou o Byakugan.\nEntão ouviram uma voz.\n— Vocês demoraram.\nOs quatro ficaram em posição.\nUma figura apareceu entre as árvores.\nEra o homem mascarado.\nO mesmo da missão anterior.\nKewyn apertou os punhos.\n— Você!\nO homem olhou diretamente para ele.\n— E seus olhos finalmente começaram a despertar.\nKewyn ativou o Byakugan.\nAs veias apareceram ao redor de seus olhos.\nO homem sorriu.\n— Interessante.\nKewyn avançou.\n— Quem é você?!",
  70: "Página 70:\nO homem desapareceu.\nKewyn olhou ao redor.\n— Onde ele foi?!\nRodrigo gritou:\n— Atrás de você!\nKewyn se virou.\nO inimigo estava a centímetros de seu rosto.\nMas Kewyn conseguiu enxergar o movimento.\nDesviou.\nGirou.\nE acertou um chute.\nBOOM!\nO homem foi lançado para trás.\nKewyn pousou em posição de ginga.\nAdriely ficou surpresa.\n— Kewyn...\nNicolas sorriu.\n— Agora sim!\nO homem mascarado se levantou lentamente.\n— Então é isso...\nEle olhou para Kewyn.\n— O sangue realmente escolheu você.\nKewyn ficou sério.\n— O que isso significa?\nO homem respondeu:\n— Pergunte ao seu mestre.\nJairo avançou.\n— Chega.\nO chakra de Jairo aumentou.\nO homem recuou.\n— Ainda não.\nEle fez um selo.\nUma cortina de fumaça apareceu.\nQuando desapareceu...\nEle havia sumido novamente.",
  71: "Página 71:\nKewyn ficou olhando para a floresta.\n— Mestre...\nJairo não respondeu.\nKewyn virou-se.\n— Você sabe quem ele é.\nJairo ficou em silêncio.\nE dessa vez...\nnão negou.\n— Sim.\nKewyn sentiu o coração acelerar.\n— Então me conte.\nJairo olhou para os quatro.\n— Está na hora de vocês conhecerem uma parte da história do Clã Ginga.\nOs quatro ficaram em silêncio.\nJairo respirou fundo.\n— Porque o Byakugan de Kewyn não apareceu por acaso.\nContinua...\n\nFim do Capítulo 6 — Os Olhos da Ginga.",
  72: "Página 72:\n• Capítulo 7 — O Segredo do Clã Ginga\nA floresta ficou em silêncio.\nO homem mascarado havia desaparecido, mas suas palavras continuavam ecoando na cabeça de Kewyn.\n\"O sangue realmente escolheu você.\"\nKewyn olhou para Jairo.\n— Você disse que ia contar.\nJairo permaneceu em silêncio por alguns segundos.\nAdriely, Rodrigo e Nicolas também esperavam.\nFinalmente, o mestre respirou fundo.\n— Está na hora.\nKewyn deu um passo à frente.\n— Na hora de quê?\nJairo olhou para os quatro.\n— De vocês conhecerem a verdadeira história do Clã Ginga.",
  73: "Página 73:\n• A origem\nJairo sentou-se perto de uma árvore.\nOs quatro Genin se acomodaram diante dele.\n— Há muitas gerações, o Clã Ginga não era conhecido apenas pela capoeira.\nRodrigo perguntou:\n— Então o que mais existia?\n— Uma técnica ocular.\nKewyn ficou imóvel.\nJairo continuou:\n— O nome dessa técnica era Olho da Ginga.\nKewyn tocou os próprios olhos.\n— O Byakugan?\n— Não exatamente.\nRodrigo franziu a testa.\n— Então existe uma ligação?\nJairo assentiu.\n— O Clã Ginga possui uma linhagem muito antiga que, em determinadas famílias, pode despertar habilidades semelhantes às do Byakugan.\nKewyn ficou confuso.\n— Mas por que ninguém nunca me contou?\n— Porque durante muitos anos essa habilidade foi considerada perigosa.",
  74: "Página 74:\n• O antigo conflito\nJairo continuou:\n— Muitos anos atrás, uma parte do Clã Ginga tentou transformar essa habilidade em uma arma.\nAdriely perguntou:\n— E conseguiram?\n— Conseguiram por algum tempo.\nJairo fechou os olhos.\n— Aqueles ninjas começaram a usar seus olhos para enxergar os pontos de chakra dos adversários.\nEles ficaram extremamente poderosos.\nNicolas perguntou:\n— E o que aconteceu?\n— O poder começou a consumir seus próprios corpos.\nKewyn ficou sério.\n— Como comigo?\nJairo assentiu.\n— Se usado sem controle, sim.\nRodrigo perguntou:\n— E essa família ainda existe?\nJairo demorou para responder.\n— É aí que a história fica complicada.",
  75: "Página 75:\n• O sangue perdido\nJairo olhou diretamente para Kewyn.\n— A linhagem responsável por esse poder quase desapareceu.\nKewyn perguntou:\n— Quase?\n— Uma pequena parte sobreviveu.\nKewyn ficou em silêncio.\n— Minha família?\nJairo assentiu.\n— Sim.\nKewyn apertou os punhos.\n— Então meus pais sabiam?\nJairo respondeu:\n— Seu pai sabia.\nKewyn arregalou os olhos.\n— Meu pai?\n— Ele sabia que um dia seus olhos poderiam despertar.\n— Então por que nunca me contou?\nJairo abaixou o olhar.\n— Porque ele queria que você tivesse uma infância normal.\nKewyn ficou emocionado.\n— E onde ele está agora?\nJairo ficou em silêncio.\nKewyn percebeu.\n— Mestre...\nJairo finalmente respondeu:\n— Seu pai desapareceu durante uma missão há muitos anos.\nKewyn abaixou a cabeça.\nEle nunca tinha ouvido aquela história daquele jeito.",
  76: "Página 76:\n• O homem mascarado\nRodrigo interrompeu:\n— E aquele homem?\nJairo respondeu:\n— Ele pertence a um grupo que procura membros dessa antiga linhagem.\nNicolas perguntou:\n— Para quê?\n— Para despertar o poder completamente.\nAdriely ficou séria.\n— E o que aconteceria se conseguissem?\nJairo olhou para Kewyn.\n— Eles poderiam usar o poder do Clã Ginga contra a própria vila.\nKewyn levantou-se.\n— Então eu vou impedir.\nJairo também se levantou.\n— Você ainda não está preparado.\nKewyn respondeu:\n— Então vou ficar preparado.\nJairo sorriu discretamente.\n— Eu sabia que diria isso.",
  77: "Página 77:\n• O treinamento começa\nNa manhã seguinte, Jairo mudou completamente o treinamento da equipe.\nNada de missões simples.\nNada de brincadeiras.\nAgora eles treinariam como verdadeiros ninjas.\nKewyn começou a praticar o Byakugan.\nAdriely passou a controlar quantidades maiores de água.\nRodrigo desenvolveu suas primeiras técnicas de vento.\nNicolas começou a dominar o Raiton.\nOs quatro treinavam juntos.",
  78: "Página 78:\n• A técnica de Adriely\nAdriely estava diante de um lago.\nEla levantou os braços.\nA água começou a subir.\nUma enorme serpente líquida surgiu.\n— Estilo Ginga: Serpente das Águas!\nA criatura avançou e atingiu uma árvore.\nBOOOOM!\nA árvore caiu.\nAdriely ficou surpresa.\n— Eu fiz isso?\nKewyn sorriu.\n— Você está ficando forte.\nEla respondeu:\n— Você também.\nEntão Adriely fechou os olhos.\nA água ao redor começou a congelar.\nUma camada de gelo cobriu o lago.\nRodrigo ficou impressionado.\n— Você conseguiu congelar uma área inteira.\nAdriely abriu os olhos.\n— Acho que ainda posso fazer mais.\nJairo observava em silêncio.\nEle sabia que o poder dela também era muito maior do que parecia.",
  79: "Página 79:\n• O vento de Rodrigo\nRodrigo estava treinando com vários alvos.\nEle começou a gingar.\nSeu chakra se espalhou pelo corpo.\nGirou.\nBaixou.\nChutou.\nFWOOSH!\nUma lâmina de vento atravessou três alvos.\nNicolas arregalou os olhos.\n— Essa foi boa!\nRodrigo ajeitou os óculos.\n— Eu sei.\nKewyn riu.\n— Está ficando convencido.\n— Estou apenas reconhecendo minha evolução.\nJairo sorriu.\n— Continue.\nRodrigo voltou à posição de luta.",
  80: "Página 80:\n• Nicolas e o raio\nNicolas treinava velocidade.\nDessa vez, não havia explosões descontroladas.\nSeu corpo se movia junto ao Raiton.\nCRACK!\nEle desapareceu de um ponto e apareceu do outro lado do campo.\nKewyn tentou acompanhar.\n— Você ficou rápido.\nNicolas sorriu.\n— Eu avisei.\n— Ainda consigo te vencer.\n— Quer tentar?\n— Depois.\nJairo observava.\nNicolas finalmente começava a dominar seu elemento.",
  81: "Página 81:\n• Kewyn\nKewyn estava sozinho.\nJairo havia colocado dezenas de pequenos alvos ao redor da floresta.\n— Ative o Byakugan.\nKewyn respirou.\nAs veias apareceram.\nByakugan!\nTudo ficou diferente.\nEle enxergava o chakra dos alvos.\nEnxergava os animais escondidos.\nEnxergava até o fluxo de chakra de seus companheiros ao longe.\nEntão percebeu algo.\nUm ponto de chakra estranho.\nMuito distante.\nKewyn ficou imóvel.\n— Mestre...\nJairo apareceu.\n— O que foi?\n— Tem alguém aqui.\nJairo ativou seu próprio chakra.\n— Onde?\nKewyn apontou.\n— Ali.\nUma figura estava escondida entre as árvores.\nJairo imediatamente ficou sério.\n— Não pode ser.\nA figura desapareceu.\nKewyn desativou o Byakugan.\n— Quem era?\nJairo olhou para o lugar.\n— Alguém que não deveria estar aqui.",
  82: "Página 82:\n• A invasão\nNaquela noite, a Vila da Ginga foi atacada.\nSinos começaram a tocar.\nCLANG!\nCLANG!\nCLANG!\nNicolas acordou imediatamente.\n— O que está acontecendo?!\nExplosões iluminaram o céu.\nAdriely saiu de casa.\nRodrigo apareceu logo depois.\nKewyn correu até eles.\n— A vila está sendo atacada!\nJairo apareceu.\n— Equipe Ginga!\nOs quatro ficaram em posição.\n— Protejam os moradores!\n— Sim!\nEles correram.\nNicolas avançou contra um invasor.\nRaiton percorreu suas pernas.\nGinga Raiton!\nEle acertou o adversário.\nRodrigo criou uma barreira de vento.\nAdriely levantou uma enorme parede de água.",
  83: "Página 83:\nKewyn ativou o Byakugan.\nE então viu.\nNo centro da vila...\no homem mascarado.\nEle estava parado diante do antigo templo do Clã Ginga.\nKewyn arregalou os olhos.\n— Ele está procurando alguma coisa.\nJairo chegou ao lado dele.\n— O templo.\n— O que tem lá?\nJairo respondeu:\n— O segredo que seu pai protegeu.\nKewyn ficou sério.\n— Então vamos impedir.\nJairo olhou para ele.\n— Não.\nKewyn se virou.\n— O quê?\n— Dessa vez, você vai confiar na sua equipe.\nJairo apontou para Adriely, Rodrigo e Nicolas.\n— Eles precisam lutar ao seu lado.\nKewyn sorriu.\n— Entendi.\nEle fechou os punhos.\n— Então vamos juntos.",
  84: "Página 84:\nOs quatro ficaram lado a lado.\nKewyn ativou o Byakugan.\nAdriely levantou a água.\nRodrigo concentrou o vento.\nNicolas carregou o corpo com eletricidade.\nE, pela primeira vez...\nos quatro liberaram seus poderes ao mesmo tempo.\nA Equipe Ginga estava pronta.\nO homem mascarado olhou para eles.\n— Finalmente.\nEle tirou lentamente a máscara.\nKewyn arregalou os olhos.\n— Você...\nO homem sorriu.\n— Vamos descobrir se o herdeiro realmente merece esse poder.\nContinua...\n\nFim do Capítulo 7 — O Segredo do Clã Ginga.",
  85: "Página 85:\n• Capítulo 8 — O Herdeiro do Clã Ginga\nA Vila da Ginga estava em caos.\nExplosões iluminavam o céu.\nCasas estavam danificadas.\nNinjas corriam pelas ruas tentando proteger os moradores.\nNo centro de tudo, diante do antigo templo do Clã Ginga, estavam os quatro Genin.\nKewyn com o Byakugan despertado.\nAdriely cercada por água.\nRodrigo com o vento girando ao redor do corpo.\nNicolas coberto por pequenas descargas elétricas.\nÀ frente deles estava o homem mascarado.\nMas agora ele havia retirado a máscara.\nKewyn olhava para ele com atenção.\n— Quem é você?\nO homem sorriu.\n— Meu nome é Raizen.",
  86: "Página 86:\nJairo imediatamente ficou sério.\n— Raizen...\nRodrigo percebeu.\n— Você conhece ele?\nJairo não respondeu.\nRaizen começou a rir.\n— Faz muitos anos, Jairo.\n— Você não deveria ter voltado.\n— E você não deveria ter escondido o garoto.\nKewyn franziu a testa.\n— Escondido?\nRaizen apontou para ele.\n— Seu mestre sabe exatamente quem você é.\nKewyn olhou para Jairo.\n— Mestre?\nJairo respirou fundo.\n— Não escute o que ele diz.\nRaizen interrompeu:\n— Pergunte a ele sobre seu pai.\nKewyn ficou imóvel.\n— Meu pai?\nRaizen sorriu.\n— Sim.\nJairo fechou os punhos.\n— Chega.",
  87: "Página 87:\n• O ataque\nRaizen fez um selo.\nO chão começou a tremer.\nBOOM!\nUma enorme onda de chakra atingiu os quatro.\n— CUIDADO! — gritou Jairo.\nAdriely levantou uma parede de água.\nCRASH!\nO impacto atingiu a barreira.\nAdriely foi empurrada para trás.\n— É muito forte!\nNicolas apareceu ao lado dela.\n— Eu ajudo!\nRaiton percorreu suas pernas.\nEle disparou contra Raizen.\n— Ginga Raiton!\nRaizen desviou facilmente.\nNicolas passou direto.\n— Droga!",
  88: "Página 88:\nRodrigo entrou em movimento.\n— Nicolas, abaixa!\nNicolas se abaixou.\nRodrigo girou.\n— Ginga do Vendaval!\nUma lâmina de vento passou por cima de Nicolas e atingiu Raizen.\nRaizen bloqueou.\n— Interessante.\nKewyn apareceu atrás dele.\nByakugan!\nEle enxergou os pontos de chakra.\n— Agora!\nKewyn atacou.\nUm golpe.\nDois.\nTrês.\nRaizen bloqueou os primeiros.\nMas Kewyn conseguiu acertar um ponto de chakra em seu braço.\nRaizen recuou.\n— Você consegue enxergar os tenketsu...\nKewyn ficou em posição de ginga.\n— Eu consigo enxergar você.\nRaizen sorriu.\n— Ainda não.",
  89: "Página 89:\n• A força de Adriely\nRaizen avançou contra Adriely.\nEla tentou recuar.\nMas ele foi rápido demais.\nKewyn percebeu.\n— Adriely!\nEla colocou as mãos para frente.\nO rio próximo começou a subir.\nUma enorme quantidade de água envolveu seu corpo.\nRaizen atravessou a primeira camada.\nAdriely então congelou a água.\nCRAAACK!\nUma parede de gelo apareceu entre os dois.\nRaizen destruiu o gelo com um golpe.\nMas Adriely já havia desaparecido.\nEla surgiu atrás dele.\n— Ginga da Maré Congelante!\nUm chute coberto de água e gelo atingiu Raizen.\nEle foi lançado contra uma parede.\nNicolas arregalou os olhos.\n— Essa foi forte!\nAdriely respirou fundo.\n— Eu ainda não terminei.\nO chão começou a congelar ao redor dela.\nJairo observou.\n— Adriely...\nEla estava liberando mais chakra do que nunca.",
  90: "Página 90:\n• Rodrigo percebe a fraqueza\nRodrigo observava Raizen.\nAlgo estava errado.\nEle ajeitou os óculos.\n— Kewyn!\n— O quê?\n— O braço esquerdo dele.\nKewyn ativou o Byakugan.\nOlhou.\n— O fluxo de chakra está irregular.\nRodrigo assentiu.\n— Exatamente.\n— Então ele está ferido?\n— Não.\nRodrigo apontou.\n— Ele está escondendo alguma coisa.\nKewyn percebeu.\nRaizen estava mantendo uma quantidade enorme de chakra concentrada no braço esquerdo.\n— Tem uma técnica ali.\nRodrigo respondeu:\n— E provavelmente é a mais perigosa.\nRaizen ouviu.\n— Vocês estão ficando inteligentes.\nEle levantou o braço.\nO chakra começou a explodir ao redor dele.\n— Mas não o suficiente.",
  91: "Página 91:\n• O ataque de Raizen\nUma enorme esfera de chakra apareceu na mão de Raizen.\nJairo gritou:\n— TODOS PARA TRÁS!\nRaizen lançou a técnica.\nBOOOOOOM!\nUma explosão atravessou a praça.\nKewyn tentou enxergar através da fumaça.\nNão conseguia.\n— Cadê ele?\nRodrigo respondeu:\n— Não vejo!\nNicolas ficou em posição.\n— Eu consigo sentir o chakra.\n— Onde?\nNicolas fechou os olhos.\n— Acima!\nRaizen estava no alto.\nEle desceu em direção a Kewyn.",
  92: "Página 92:\nKewyn ativou o Byakugan.\nTudo ficou lento.\nEle enxergou o movimento.\nEsquerda.\nDireita.\nBaixo.\nKewyn desviou por poucos centímetros.\nRaizen errou.\nKewyn colocou a mão no chão.\nGirou o corpo.\nE acertou uma sequência de golpes.\nTUM!\nTUM!\nTUM!\nRaizen recuou.\nKewyn continuou.\n— Ginga dos Cem Olhares!\nEle acertou vários pontos de chakra.\nRaizen perdeu o equilíbrio.\nKewyn preparou o último golpe.\nMas...\nRaizen segurou seu braço.\n— Você é forte.\nKewyn arregalou os olhos.\n— Solta!\nRaizen apertou.\n— Mas ainda não entende o que seus olhos realmente podem fazer.",
  93: "Página 93:\n• O segundo despertar\nDe repente, Kewyn sentiu uma dor enorme nos olhos.\n— AAAAAH!\nSeu Byakugan começou a mudar.\nAs veias ao redor dos olhos ficaram ainda mais fortes.\nEle começou a enxergar muito além.\nConseguia ver o chakra de todos na praça.\nDe cada árvore.\nDe cada pessoa.\nAté mesmo o fluxo de chakra dentro de Raizen.\nE então viu algo.\nUma marca.\nUm símbolo antigo.\nNo peito de Raizen.\nKewyn arregalou os olhos.\n— Esse símbolo...\nJairo ficou pálido.\n— Kewyn, desative o Byakugan!\n— Eu consigo ver!\n— AGORA!",
  94: "Página 94:\nMas era tarde.\nO chakra dos olhos de Kewyn explodiu.\nBOOOOM!\nUma onda de energia empurrou Raizen para trás.\nKewyn caiu de joelhos.\nSeu Byakugan desapareceu.\nEle respirava com dificuldade.\nRaizen olhou para ele.\nPela primeira vez...\nestava assustado.\n— Impossível.\nJairo correu até Kewyn.\n— Você está bem?\nKewyn levantou a cabeça.\n— Eu vi uma marca nele.\n— Que marca?\n— A mesma marca que está no templo.\nJairo ficou em silêncio.",
  95: "Página 95:\n• O segredo do templo\nRaizen olhou para o antigo templo.\n— Então você descobriu.\nKewyn se levantou.\n— O que tem lá dentro?\nRaizen respondeu:\n— A verdade.\nKewyn avançou.\n— Então eu vou descobrir.\nRaizen sorriu.\n— Não hoje.\nEle fez um selo.\nUma fumaça negra começou a cobrir seu corpo.\nJairo tentou atacá-lo.\nMas Raizen desapareceu.\nAntes de sumir completamente, deixou uma última frase:\n— Quando você despertar completamente, Kewyn...\nA voz ecoou pela praça.\n— ...seu próprio clã terá medo de você.\nE então ele desapareceu.",
  96: "Página 96:\n• Depois da batalha\nA invasão havia terminado.\nOs inimigos restantes fugiram.\nOs ninjas da Vila da Ginga começaram a reconstruir as áreas destruídas.\nKewyn estava sentado diante do templo.\nAdriely sentou ao lado dele.\n— Você está bem?\n— Estou.\nRodrigo se aproximou.\n— Você quase perdeu o controle do Byakugan.\nKewyn respondeu:\n— Eu sei.\nNicolas sentou no chão.\n— Mas você salvou a gente.\nKewyn olhou para os três.\n— Nós salvamos uns aos outros.\nAdriely sorriu.\n— Isso.",
  97: "Página 97:\nJairo chegou.\nKewyn levantou.\n— Mestre.\n— Sim?\n— Quero entrar no templo.\nJairo ficou sério.\n— Ainda não.\n— Por quê?\n— Porque você precisa estar preparado.\nKewyn respondeu:\n— E quando vou estar?\nJairo olhou para seus olhos.\n— Quando conseguir despertar o Byakugan sem deixar que ele controle você.\nKewyn apertou os punhos.\n— Então vou treinar até conseguir.\nJairo sorriu.\n— É exatamente isso que você deve fazer.",
  98: "Página 98:\nEnquanto isso...\nMuito longe dali, Raizen caminhava por uma caverna.\nOutro homem o esperava.\n— Você conseguiu?\nRaizen balançou a cabeça.\n— Não.\n— E o garoto?\nRaizen sorriu.\n— Ele despertou mais do que esperávamos.\nO homem ficou preocupado.\n— Então o herdeiro é realmente especial?\nRaizen respondeu:\n— Não.\nEle olhou para a lua através de uma abertura na caverna.\n— Ele é muito mais perigoso do que isso.\nO homem perguntou:\n— O que faremos agora?\nRaizen respondeu:\n— Esperaremos.\n— Pelo quê?\nRaizen sorriu.\n— Pelo próximo despertar.",
  99: "Página 99:\nNaquela noite, Kewyn dormiu profundamente.\nE sonhou.\nEle estava diante de uma enorme porta.\nAtrás dela havia uma luz branca.\nUma voz chamou:\n— Kewyn...\nEle se aproximou.\n— Quem está aí?\nA voz respondeu:\n— Você ainda não está pronto.\nKewyn colocou a mão na porta.\n— Eu vou descobrir quem sou.\nA porta começou a tremer.\nUma pequena rachadura apareceu.\nE, do outro lado...\ndois olhos brancos se abriram.\nKewyn acordou assustado.\nSentou-se na cama.\nRespirou rapidamente.\nE olhou para a janela.\nA lua iluminava seu quarto.\nKewyn tocou os próprios olhos.\n— O que está acontecendo comigo?\nEle ainda não sabia.\nMas seu verdadeiro despertar havia começado.\nContinua...\n\nFim do Capítulo 8 — O Herdeiro do Clã Ginga.",
  100: "Página 100:\n• Capítulo 9 — A Porta dos Ancestrais\nA noite havia passado.\nMas Kewyn não conseguia esquecer o sonho.\nAquela porta.\nAquela voz.\nE aqueles dois olhos brancos do outro lado.\n\"Você ainda não está pronto.\"\nKewyn estava sentado na cama, olhando para as próprias mãos.\n— O que existe atrás daquela porta?\nEle fechou os olhos.\nPor um instante, sentiu novamente aquela presença.\nTum.\nSeu coração bateu mais forte.\nKewyn abriu os olhos.\n— Eu preciso descobrir.",
  101: "Página 101:\n• Uma manhã diferente\nNa manhã seguinte, Kewyn chegou ao campo de treinamento antes de todos.\nJairo já estava esperando.\n— Você teve o sonho novamente?\nKewyn parou.\n— Como você sabe?\nJairo respondeu:\n— Porque eu conheço esse olhar.\nKewyn ficou sério.\n— Você já viu aquela porta?\nJairo demorou alguns segundos.\n— Sim.\nKewyn arregalou os olhos.\n— Então você sabe o que é!\n— Sei o suficiente.\n— Então me conta!\nJairo balançou a cabeça.\n— Não posso.\nKewyn ficou irritado.\n— Todo mundo sabe alguma coisa sobre mim, menos eu!\nJairo olhou diretamente para ele.\n— Porque algumas verdades precisam ser descobertas, não simplesmente contadas.\nKewyn respirou fundo.\n— Então me treine.\nJairo sorriu.\n— Era exatamente isso que eu esperava.",
  102: "Página 102:\n• O treinamento dos quatro\nJairo reuniu a equipe.\n— A partir de hoje, o treinamento de vocês será dividido em quatro partes.\nRodrigo ajeitou os óculos.\n— Cada um vai treinar sua especialidade?\n— Exatamente.\nJairo apontou para Kewyn.\n— Kewyn: percepção e combate com o Byakugan.\nDepois para Adriely.\n— Adriely: controle de água e gelo.\nRodrigo.\n— Rodrigo: vento e estratégia.\nE finalmente Nicolas.\n— Nicolas: velocidade e Raiton.\nNicolas abriu um sorriso.\n— Finalmente!\nJairo continuou:\n— Mas existe uma quinta parte.\nOs quatro ficaram curiosos.\n— Trabalho em equipe.",
  103: "Página 103:\n• Kewyn e o Byakugan\nKewyn ficou diante de vários alvos.\nJairo colocou uma venda sobre seus olhos.\n— O quê?\n— Você não pode depender apenas da visão.\nKewyn respirou fundo.\n— Então como vou enxergar?\n— Pelo chakra.\nKewyn fechou os olhos.\nTentou sentir.\nNada.\nUma pedra foi lançada contra ele.\nFWOOSH!\nKewyn desviou por pouco.\n— Mais uma!\nOutra pedra.\nEle desviou.\nOutra.\nDessa vez, Kewyn girou e segurou a pedra.\n— Peguei!\nJairo sorriu.\n— Está começando a perceber.\nKewyn retirou a venda.\n— Posso usar o Byakugan agora?\n— Não.\n— Por quê?\n— Porque seu verdadeiro objetivo é aprender a lutar com ou sem ele.\nKewyn entendeu.\nEle entrou na ginga.\n— Então vamos de novo.",
  104: "Página 104:\n• Adriely e o gelo\nAdriely estava diante do lago.\nEla levantou as mãos.\nA água começou a subir.\nFWOOSH!\nUma enorme onda se formou.\n— Agora...\nEla fechou os dedos.\nA onda começou a congelar.\nCRACK!\nO gelo se espalhou.\nAdriely abriu os olhos.\n— Mais!\nEla aumentou o chakra.\nUma ponte de gelo surgiu sobre o lago.\nNicolas ficou impressionado.\n— Você construiu uma ponte!\nAdriely sorriu.\n— E consigo destruir também.\nEla moveu a mão.\nA ponte se transformou em dezenas de pequenas lanças de gelo.\nRodrigo arregalou os olhos.\n— Isso é perigoso.\nAdriely desfez a técnica imediatamente.\n— Ainda preciso controlar melhor.\nJairo assentiu.\n— Exatamente.\n— Mas estou melhorando.\n— Muito.",
  105: "Página 105:\n• Rodrigo cria sua primeira técnica\nRodrigo estava diante de uma fileira de alvos.\nEle começou a gingar.\nEsquerda.\nDireita.\nGiro.\nAbaixou.\nSeu chakra de vento começou a circular.\n— Ginga do Vendaval!\nUma corrente de vento avançou.\nMas, dessa vez, Rodrigo não lançou apenas uma rajada.\nEle girou novamente.\nO vento mudou de direção.\nAtingiu outro alvo.\nDepois outro.\nE outro.\nBOOM!\nBOOM!\nBOOM!\nNicolas ficou impressionado.\n— Você acertou todos!\nRodrigo ajeitou os óculos.\n— Eu disse que precisão é melhor que força.\nKewyn riu.\n— Está se achando.\n— Talvez.",
  106: "Página 106:\n• Nicolas contra o trovão\nNicolas estava no topo de uma pequena montanha.\nJairo colocou vários alvos em diferentes pontos.\n— Seu objetivo é acertar todos em menos de dez segundos.\nNicolas sorriu.\n— Fácil.\n— Sem perder o controle do Raiton.\nNicolas ficou sério.\n— Isso complica.\n— Exatamente.\nJairo levantou a mão.\n— Comece.\nNicolas ativou o Raiton.\nCRACK!\nDesapareceu.\nPrimeiro alvo.\nBOOM!\nSegundo.\nTerceiro.\nQuarto.\nA velocidade aumentou.\nMas então...\nCRACK!\nNicolas tropeçou.\nCaiu no chão.\n— Agh!\nKewyn começou a rir.\n— \"Fácil\", hein?\nNicolas levantou.\n— Eu estava testando o terreno!\nRodrigo respondeu:\n— Claro.\nAdriely começou a rir.\nNicolas apontou para os três.\n— Vocês vão ver!",
  107: "Página 107:\n• A nova missão\nDepois de semanas de treinamento, Jairo recebeu uma mensagem.\nUm mensageiro apareceu no campo.\n— Mestre Jairo.\nJairo abriu o pergaminho.\nSeu rosto mudou.\nKewyn percebeu.\n— O que aconteceu?\nJairo fechou o pergaminho.\n— Temos uma missão.\n— Que tipo?\n— Investigação.\nRodrigo perguntou:\n— Sobre o quê?\nJairo olhou para Kewyn.\n— O antigo templo.\nKewyn ficou imediatamente sério.\n— O templo?\nJairo assentiu.\n— Encontraram marcas de chakra dentro dele.\nAdriely perguntou:\n— De quem?\n— Ainda não sabemos.\nNicolas fechou os punhos.\n— Então vamos descobrir.",
  108: "Página 108:\n• O templo\nA equipe chegou ao antigo templo ao anoitecer.\nEra uma construção enorme.\nPedras antigas cobriam as paredes.\nSímbolos do Clã Ginga estavam espalhados por todos os lados.\nKewyn ativou o Byakugan.\nByakugan!\nEle olhou para dentro.\n— Tem chakra.\nJairo perguntou:\n— Onde?\nKewyn apontou para uma parede.\n— Ali.\nRodrigo se aproximou.\n— Parece uma passagem.\nAdriely colocou a mão na parede.\n— Está congelada.\nKewyn olhou.\n— Congelada?\nAdriely balançou a cabeça.\n— Não fui eu.\nNicolas ficou sério.\n— Então quem fez isso?\nJairo respondeu:\n— Vamos descobrir.",
  109: "Página 109:\n• A porta\nRodrigo encontrou uma pequena inscrição.\nEle limpou a poeira.\n— Aqui tem alguma coisa escrita.\nKewyn se aproximou.\nA inscrição dizia:\n\"Somente aquele que enxerga além da própria visão poderá abrir o caminho.\"\nKewyn sentiu um arrepio.\n— É para mim.\nJairo ficou em silêncio.\nKewyn colocou a mão na pedra.\nNada aconteceu.\nEle ativou o Byakugan.\nAs veias apareceram.\nA parede começou a tremer.\nCRACK.\nUma linha surgiu.\nA pedra se abriu lentamente.\nUma passagem apareceu.\nDo outro lado havia uma enorme escadaria descendo para a escuridão.\nNicolas olhou para baixo.\n— Isso parece uma péssima ideia.\nRodrigo respondeu:\n— Concordo.\nAdriely sorriu.\n— Então provavelmente precisamos ir.\nKewyn começou a descer.\n— Vamos.\nJairo ficou atrás deles.\n— Não se afastem.",
  110: "Página 110:\n• O salão subterrâneo\nDepois de vários minutos, chegaram a uma enorme sala subterrânea.\nNo centro havia uma estátua.\nUm guerreiro do Clã Ginga.\nEle estava em posição de capoeira.\nMas seus olhos eram completamente brancos.\nKewyn ficou olhando.\n— É ele.\nJairo perguntou:\n— Quem?\nKewyn respondeu:\n— A pessoa que apareceu no meu sonho.\nJairo ficou sério.\nNo peito da estátua havia o mesmo símbolo que Kewyn havia visto em Raizen.\nRodrigo percebeu.\n— Então Raizen está ligado a este lugar.\n— Sim — disse Jairo.\nDe repente...\nCLANG!\nA porta atrás deles se fechou.\nNicolas virou.\n— Ah, ótimo.\nAdriely olhou ao redor.\n— Estamos presos.\nJairo levantou a mão.\n— Todos fiquem calmos.",
  111: "Página 111:\nEntão uma voz ecoou pelo salão.\n— Finalmente vocês chegaram.\nKewyn ativou o Byakugan.\n— Tem alguém aqui!\nUma sombra surgiu atrás da estátua.\nRaizen apareceu.\nMas dessa vez...\nele não estava sozinho.\nHavia três ninjas ao lado dele.\nRaizen sorriu.\n— Bem-vindos ao lugar onde a história do Clã Ginga começou.\nKewyn entrou em posição de luta.\n— O que você quer?\nRaizen respondeu:\n— Não quero nada de você.\nEle olhou para os quatro.\n— Quero ver se vocês são realmente dignos de carregar o nome da Equipe Ginga.\nJairo ficou sério.\n— Então é isso.\nRaizen fez um selo.\nAs portas do salão começaram a se fechar completamente.\n— Sobrevivam ao teste.\nKewyn olhou para seus companheiros.\nAdriely preparou a água.\nRodrigo concentrou o vento.\nNicolas ativou o Raiton.\nKewyn ativou o Byakugan.\nOs quatro ficaram lado a lado.\nE então...\nos três ninjas avançaram.\nContinua...\n\nFim do Capítulo 9 — A Porta dos Ancestrais.",
  112: "Página 112:\n• Capítulo 10 — A Batalha no Templo\nOs três ninjas avançaram ao mesmo tempo.\nSHUUU!\nKewyn ativou o Byakugan.\nAs veias ao redor de seus olhos apareceram.\n— Três inimigos... e todos têm bastante chakra.\nRodrigo ajeitou os óculos.\n— O da esquerda é o mais rápido.\nAdriely olhou para o da direita.\n— Aquele está usando chakra de fogo.\nNicolas sorriu.\n— Então eu fico com o mais rápido.\nKewyn olhou para ele.\n— Tem certeza?\n— Tenho.\nJairo permaneceu atrás.\n— Não se esqueçam do que aprenderam.\nKewyn respirou fundo.\n— Equipe Ginga.\nOs quatro entraram em posição.\n— Ginga!",
  113: "Página 113:\n• Nicolas contra o Relâmpago Negro\nO inimigo mais rápido desapareceu.\nCRACK!\nNicolas ativou o Raiton imediatamente.\nOs dois surgiram no centro do salão.\nBOOM!\nPunho contra punho.\nOs dois recuaram.\nNicolas sorriu.\n— Você é rápido.\nO inimigo respondeu:\n— E você ainda é lento.\nNicolas arregalou os olhos.\n— O quê?!\nO adversário desapareceu novamente.\nNicolas fechou os olhos.\nTentou sentir o chakra.\nCRACK!\nEle virou o corpo no último instante.\nUm chute passou raspando por seu rosto.\n— Te achei!\nNicolas girou.\n— Ginga Raiton!\nA eletricidade percorreu sua perna.\nO chute acertou o adversário no peito.\nBOOM!\nEle foi lançado contra uma coluna.\nNicolas respirou fundo.\n— Eu não sou tão lento assim.\nMas o inimigo se levantou.\nE uma eletricidade negra começou a cobrir seu corpo.\nNicolas ficou sério.\n— Isso não é Raiton normal...",
  114: "Página 114:\n• Adriely contra o fogo\nDo outro lado do salão, o segundo inimigo fez um selo.\nFWOOSH!\nUma enorme bola de fogo surgiu.\nAdriely levantou as mãos.\n— Estilo Água!\nUma parede de água apareceu.\nSHHHHH!\nO fogo atingiu a água.\nUma enorme nuvem de vapor cobriu o salão.\nAdriely não conseguia enxergar.\n— Onde ele está?\nUma sombra surgiu dentro da fumaça.\nO inimigo atacou.\nAdriely bloqueou.\nMas foi empurrada para trás.\nEla deslizou pelo chão.\n— Ele é forte...",
  115: "Página 115:\nEntão ouviu a voz de Kewyn.\n— Adriely!\nEla olhou para ele.\n— O quê?\n— Não lute contra o fogo dele.\nAdriely entendeu.\n— Eu posso usar o ambiente.\nEla olhou para o chão.\nHavia pequenas poças de água espalhadas pelo salão.\nAdriely sorriu.\n— Entendi.\nEla estendeu a mão.\nTodas as poças começaram a flutuar.\nO inimigo arregalou os olhos.\n— O quê?!\nA água envolveu seus braços e pernas.\nAdriely fechou a mão.\nCRACK!\nA água congelou.\nO inimigo ficou preso.\n— Ginga do Gelo!\nAdriely girou e acertou um chute.\nO adversário foi lançado contra a parede.",
  116: "Página 116:\n• Rodrigo contra a estratégia\nO terceiro inimigo não atacava.\nEle observava.\nRodrigo percebeu.\n— Você está esperando.\nO homem sorriu.\n— Exatamente.\nRodrigo ajeitou os óculos.\n— Então você é o estrategista.\n— E você também.\nOs dois ficaram se encarando.\nO inimigo lançou três kunais.\nRodrigo desviou.\nDepois quatro.\nRodrigo desviou novamente.\n— Você está tentando me empurrar para um lugar específico.\nO inimigo parou.\nRodrigo sorriu.\n— Eu sabia.\nEle girou.\n— Ginga do Vendaval!\nO vento mudou completamente a direção das kunais.\nElas voltaram contra o próprio inimigo.\nO homem desviou por pouco.\n— Interessante.\nRodrigo respondeu:\n— Eu observo bastante.",
  117: "Página 117:\n• Kewyn entra na batalha\nKewyn observava os três combates.\nSeu Byakugan permitia enxergar os fluxos de chakra dos inimigos.\nEntão percebeu alguma coisa.\n— Esperem!\nOs três olharam.\n— Esses caras estão conectados.\nRodrigo entendeu primeiro.\n— O chakra deles está ligado.\nJairo ficou sério.\n— Exatamente.\nKewyn olhou para Raizen.\n— Foi você que fez isso?\nRaizen sorriu.\n— Não.\nKewyn ficou confuso.\n— Então quem?\nRaizen olhou para a estátua no centro do salão.\n— O templo.",
  118: "Página 118:\n• O verdadeiro teste\nAs paredes começaram a tremer.\nBOOOOM!\nOs três inimigos recuaram.\nUma enorme quantidade de chakra começou a sair da estátua.\nKewyn ficou paralisado.\nSeu Byakugan mostrava algo que ninguém mais conseguia ver.\nDentro da estátua havia uma espécie de núcleo de chakra.\nE aquele chakra...\nera parecido com o dele.\n— Mestre...\nJairo respondeu:\n— Eu sei.\nKewyn perguntou:\n— O que é aquilo?\nJairo finalmente revelou:\n— É o chakra dos antigos membros do Clã Ginga.\nSilêncio.\nRodrigo ficou impressionado.\n— Então essa estátua está guardando chakra há gerações?\nJairo assentiu.\n— Sim.\nAdriely perguntou:\n— Por quê?\nJairo respondeu:\n— Para escolher o próximo guardião.\nKewyn olhou para a estátua.\n— Guardião?\nRaizen sorriu.\n— Agora você está começando a entender.",
  119: "Página 119:\n• O escolhido\nA estátua começou a brilhar.\nUma luz branca atingiu Kewyn.\nFWOOSH!\nKewyn foi levantado alguns centímetros do chão.\n— Kewyn! — gritou Adriely.\nJairo tentou se aproximar.\nMas uma barreira o impediu.\n— Não!\nKewyn estava sozinho dentro da barreira.\nEle ouviu novamente aquela voz.\n\"Você quer conhecer a verdade?\"\nKewyn respondeu:\n— Quero.\n\"Então abra os olhos.\"\nKewyn abriu os olhos.\nO Byakugan despertou.\nMas dessa vez havia algo diferente.\nEle conseguia enxergar muito mais longe.\nConseguia enxergar o passado.\nViu antigos ninjas do Clã Ginga.\nViu guerreiros treinando capoeira.\nViu batalhas.\nViu pessoas protegendo a vila.\nE então viu um jovem ninja.\nKewyn reconheceu imediatamente.\n— Pai...\nSeu pai estava diante da mesma estátua.\nE alguém estava conversando com ele.\nKewyn tentou ouvir.\nMas antes que pudesse...\na visão desapareceu.",
  120: "Página 120:\n• O despertar incompleto\nKewyn caiu no chão.\nAdriely correu até ele.\n— Kewyn!\nEle respirava rapidamente.\n— Eu vi meu pai.\nJairo ficou imóvel.\n— O que você viu?\nKewyn olhou para ele.\n— Ele esteve aqui.\nJairo fechou os olhos.\n— Sim.\nKewyn ficou irritado.\n— Você sabia!\n— Sim.\n— Por que nunca me contou?!\nJairo não respondeu.\nKewyn apertou os punhos.\n— Eu quero saber a verdade!\nRaizen observava de longe.\nEntão começou a rir.\n— A verdade vai destruir tudo o que você acredita.\nKewyn se levantou.\n— Então eu vou descobrir mesmo assim.\nRaizen sorriu.\n— É exatamente o que seu pai diria.\nKewyn ficou em silêncio.",
  121: "Página 121:\nRaizen fez um selo.\nUma passagem apareceu atrás dele.\n— Nosso encontro termina aqui.\nNicolas correu.\n— Você não vai fugir!\nRaizen olhou para ele.\n— Ainda não chegou a hora de lutarmos de verdade.\nEle desapareceu.\nOs três inimigos também desapareceram.\nO templo voltou ao silêncio.",
  122: "Página 122:\n• A promessa\nKewyn ficou diante da estátua.\nAdriely, Rodrigo e Nicolas ficaram ao seu lado.\nKewyn olhou para os três.\n— Eu não sei o que aconteceu com meu pai.\nRodrigo respondeu:\n— Então vamos descobrir.\nAdriely assentiu.\n— Juntos.\nNicolas levantou o punho.\n— Até o fim.\nKewyn sorriu.\nEle colocou o punho no centro.\nOs outros três fizeram o mesmo.\n— Equipe Ginga.\nE naquele momento, Kewyn fez uma promessa:\n— Eu vou descobrir toda a verdade sobre meu pai, sobre o Clã Ginga e sobre esses olhos.\nEle olhou para a estátua.\n— E quando eu descobrir...\n— ninguém vai conseguir esconder de mim.\n\nContinua...\n\nFim do Capítulo 10 — A Batalha no Templo.",
  123: "Página 123:\n• Capítulo 11 — O Caminho do Guardião\nO templo estava silencioso.\nA batalha havia terminado, mas Kewyn continuava diante da antiga estátua.\nEle não conseguia esquecer a imagem que havia visto.\nSeu pai.\nNaquele mesmo templo.\nDiante daquela mesma estátua.\nE agora havia uma pergunta que não saía de sua cabeça:\nPor que ele esteve ali?",
  124: "Página 124:\n• O retorno à vila\nA Equipe Ginga voltou para a Vila da Ginga ao amanhecer.\nNinguém conversava muito.\nNicolas caminhava com os braços atrás da cabeça.\n— Então... alguém vai falar alguma coisa?\nRodrigo ajeitou os óculos.\n— Sobre o quê?\n— Sobre tudo isso!\nAdriely olhou para Kewyn.\n— Ele precisa de um tempo.\nKewyn continuava calado.\nJairo caminhava alguns metros à frente.\nQuando chegaram aos portões da vila, vários ninjas vieram recebê-los.\nUm deles perguntou:\n— Mestre Jairo, o que aconteceu?\nJairo respondeu:\n— Encontramos informações importantes.\n— Sobre os invasores?\nJairo olhou para Kewyn.\n— Sobre o Clã Ginga.\nOs ninjas ficaram em silêncio.",
  125: "Página 125:\n• A reunião dos mestres\nNaquela tarde, Jairo foi chamado para uma reunião com os líderes da vila.\nKewyn, Adriely, Rodrigo e Nicolas esperavam do lado de fora.\nNicolas estava inquieto.\n— Por que está demorando tanto?\nRodrigo respondeu:\n— Porque provavelmente estão discutindo algo importante.\n— Isso eu sei.\nAdriely perguntou:\n— Você acha que vão contar para o Kewyn o que aconteceu?\nRodrigo olhou para a porta.\n— Se depender do mestre Jairo, sim.\nKewyn permaneceu sentado.\nEle estava pensando no sonho.\nNa estátua.\nNo pai.\nE na voz que havia ouvido.\nEntão a porta se abriu.\nJairo saiu.\n— Kewyn.\nO garoto levantou.\n— Sim?\n— Entre.\nKewyn olhou para os amigos.\nAdriely sorriu.\n— Vai.\nEle entrou.",
  126: "Página 126:\n• A verdade sobre o pai\nHavia cinco pessoas dentro da sala.\nJairo estava de um lado.\nNo centro estava o líder da Vila da Ginga.\nEle colocou um pergaminho sobre a mesa.\n— Kewyn, você tem o direito de saber algumas coisas.\nKewyn ficou atento.\n— Sobre meu pai?\nO líder assentiu.\n— Seu pai se chamava Kaio.\nKewyn ficou imóvel.\nEra a primeira vez que alguém falava sobre ele daquela maneira.\n— Ele era um dos ninjas mais habilidosos do Clã Ginga.\nKewyn perguntou:\n— Ele tinha o Byakugan?\nO líder respondeu:\n— Sim.\nKewyn abaixou os olhos.\n— Então ele era como eu.\n— Em alguns aspectos.\nO líder abriu o pergaminho.\nHavia um desenho antigo de um ninja usando o Byakugan.\n— Seu pai investigava o desaparecimento de antigos documentos do Clã Ginga.\nKewyn perguntou:\n— Documentos sobre o quê?\n— Sobre o Guardião.\nKewyn se lembrou da estátua.\n— Aquele que escolhe alguém?\n— Exatamente.",
  127: "Página 127:\n• O Guardião\nO líder explicou:\n— Segundo as antigas histórias, o Guardião não é apenas uma pessoa.\nKewyn franziu a testa.\n— Como assim?\n— É uma função.\nUm título passado de geração em geração.\nRodrigo, que havia entrado silenciosamente na sala com Adriely e Nicolas, perguntou:\n— E o que o Guardião protege?\nO líder respondeu:\n— O Núcleo da Ginga.\nOs quatro ficaram atentos.\n— O que é isso? — perguntou Adriely.\n— Uma fonte antiga de chakra criada pelos primeiros membros do clã.\nNicolas arregalou os olhos.\n— Então aquela estátua...\n— Está ligada ao Núcleo.\nKewyn apertou os punhos.\n— E meu pai?\nO líder ficou sério.\n— Seu pai descobriu que alguém queria roubar esse poder.",
  128: "Página 128:\n• O desaparecimento\nKewyn finalmente perguntou:\n— Foi por isso que ele desapareceu?\nJairo respondeu:\n— Sim.\nKewyn olhou para o mestre.\n— O que aconteceu com ele?\nJairo respirou fundo.\n— Durante uma missão, Kaio descobriu a localização de um grupo que procurava o Núcleo.\n— Raizen?\n— Entre outros.\nKewyn ficou em silêncio.\n— Seu pai entrou no esconderijo deles.\n— E voltou?\nJairo abaixou a cabeça.\n— Não.\nKewyn sentiu o coração apertar.\n— Então ele morreu?\nSilêncio.\nJairo respondeu:\n— Nós nunca encontramos o corpo.\nKewyn levantou os olhos.\n— Então existe uma possibilidade...\nJairo assentiu.\n— Sim.\n— Ele pode estar vivo.\n— Pode.\nKewyn apertou os punhos.\nPela primeira vez, uma pequena esperança apareceu em seu rosto.",
  129: "Página 129:\n• Uma nova missão\nO líder da vila se levantou.\n— É por isso que vocês quatro receberão uma missão especial.\nRodrigo perguntou:\n— Qual?\nO líder colocou outro pergaminho sobre a mesa.\n— Encontrar informações sobre o paradeiro de Kaio.\nKewyn imediatamente pegou o pergaminho.\n— Eu vou.\nJairo respondeu:\n— Não será uma missão simples.\nNicolas sorriu.\n— Melhor ainda.\nAdriely olhou para ele.\n— Você não está preocupado?\n— Estou.\nNicolas fechou os punhos.\n— Mas estamos juntos.\nRodrigo concordou.\n— E precisamos descobrir o que Raizen está planejando.\nKewyn olhou para os três.\n— Obrigado.",
  130: "Página 130:\n• O treinamento final\nAntes da missão, Jairo decidiu dar aos quatro uma última semana de treinamento.\n— Vocês enfrentarão inimigos mais fortes dessa vez.\nKewyn perguntou:\n— Então precisamos ficar mais fortes.\n— Sim.\nJairo olhou para cada um.\n— Mas não tentem vencer sozinhos.\nKewyn sorriu.\n— Aprendemos isso no primeiro teste.\n— E continuam aprendendo.",
  131: "Página 131:\n• Kewyn\nKewyn treinou o Byakugan.\nDessa vez, conseguiu mantê-lo ativo durante muito mais tempo.\nTambém começou a desenvolver uma nova maneira de lutar.\nEle não queria depender somente dos golpes tradicionais.\nQueria combinar a visão do Byakugan com a movimentação da capoeira.\nJairo observou.\n— Você está começando a criar seu próprio estilo.\nKewyn girou.\n— Quero que ninguém consiga prever meus movimentos.\n— Então não seja previsível.\nKewyn sorriu.",
  132: "Página 132:\n• Adriely\nAdriely treinou água e gelo.\nEla conseguiu criar uma pequena esfera de água.\nDepois congelou.\nDepois descongelou.\nDepois transformou novamente em água.\nJairo ficou impressionado.\n— Você está aprendendo a alternar os elementos rapidamente.\nAdriely respondeu:\n— Quero conseguir controlar a água em qualquer lugar.\nJairo perguntou:\n— Mesmo em um deserto?\nAdriely sorriu.\n— Principalmente no deserto.",
  133: "Página 133:\n• Rodrigo\nRodrigo desenvolveu uma técnica nova.\nEle começou a girar.\nO vento formou um círculo ao seu redor.\n— Ginga: Redemoinho Cortante!\nO vento avançou em várias direções.\nJairo assentiu.\n— Muito bom.\nRodrigo ajeitou os óculos.\n— Eu ainda posso melhorar.\n— Esse é o espírito.",
  134: "Página 134:\n• Nicolas\nNicolas treinou seu Raiton até o limite.\nSeu corpo começou a ficar coberto de eletricidade.\nCRACK!\nEle desapareceu.\nReapareceu.\nDesapareceu novamente.\nDessa vez, conseguiu parar sem cair.\nNicolas abriu um sorriso.\n— Consegui!\nKewyn bateu no ombro dele.\n— Agora você não caiu.\n— Engraçadinho.",
  135: "Página 135:\n• A partida\nUma semana depois, a Equipe Ginga estava pronta.\nQuatro mochilas.\nQuatro bandanas.\nQuatro ninjas.\nJairo estava diante deles.\n— A missão pode durar vários dias.\nAdriely perguntou:\n— Para onde vamos?\nJairo respondeu:\n— Para o norte.\nRodrigo abriu o mapa.\n— Há uma região montanhosa lá.\n— Exatamente.\nNicolas perguntou:\n— E o que estamos procurando?\nJairo olhou para Kewyn.\n— Uma antiga base do Clã Ginga.\nKewyn ficou sério.\n— Talvez encontremos alguma pista do meu pai.\nJairo assentiu.\n— Talvez.",
  136: "Página 136:\nOs quatro começaram a caminhar.\nKewyn olhou uma última vez para a Vila da Ginga.\nDepois seguiu seus companheiros.\nMas ninguém percebeu que, muito longe dali, alguém observava a partida.\nRaizen estava no alto de uma montanha.\nAo lado dele estava uma figura desconhecida.\n— Eles estão indo para o norte — disse Raizen.\nA figura perguntou:\n— Devemos segui-los?\nRaizen sorriu.\n— Não.\n— Por quê?\nRaizen olhou para Kewyn ao longe.\n— Porque eles estão indo exatamente para onde queremos.\nA figura ficou em silêncio.\nRaizen continuou:\n— Deixem que encontrem a antiga base.\nEle fechou os olhos.\n— Lá, Kewyn finalmente descobrirá a verdade.\nE talvez...\nnão consiga voltar depois de descobri-la.\n\nContinua...\n\nFim do Capítulo 11 — O Caminho do Guardião."


};

let usuarioAtual = null;
let modoVisitante = false;
let indiceAtual = 0;

// Referências de Elementos HTML
const pageNumElement = document.getElementById("page-num");
const totalPagesElement = document.getElementById("total-pages");
const pageTextElement = document.getElementById("page-text");
const prevBtn = document.getElementById("prev-btn");
const nextBtn = document.getElementById("next-btn");
const swipeArea = document.getElementById("swipe-area");

const welcomeModal = document.getElementById("welcome-modal");
const continueModal = document.getElementById("continue-modal");
const googleLoginBtn = document.getElementById("save-user-btn");
const guestBtn = document.getElementById("guest-btn");

const continueSection = document.getElementById("continue-reading-section");
const startFromBeginningBtn = document.getElementById("start-from-beginning-btn");
const backToHomeBtn = document.getElementById("back-to-home-btn");

// CONTROLAR SPLASH SCREEN (TELA DE ABERTURA)
window.addEventListener('DOMContentLoaded', () => {
  const splash = document.getElementById('splash-screen');
  setTimeout(() => {
    if (splash) {
      splash.classList.add('hidden');
    }
  }, 2000);
});

if (totalPagesElement) {
  totalPagesElement.textContent = TOTAL_PAGINAS;
}

function obterOuCriarIdDispositivo() {
  let deviceId = localStorage.getItem("leitor_device_id");
  if (!deviceId) {
    deviceId = "guest_" + Math.random().toString(36).substring(2, 15);
    localStorage.setItem("leitor_device_id", deviceId);
  }
  return deviceId;
}

// ATUALIZAR INTERFACE DA TELA DE SELEÇÃO
function atualizarInterfaceSelecao(paginaSalva) {
  const continueBtn = document.getElementById("continue-btn");
  const cap1Status = document.getElementById("progress-status");

  if (paginaSalva > 1) {
    if (continueSection) continueSection.classList.remove("hidden");
    if (cap1Status) cap1Status.textContent = `Parou na Página ${paginaSalva}`;
    if (continueBtn) {
      continueBtn.onclick = () => abrirLeitor(paginaSalva - 1);
    }
  } else {
    if (continueSection) continueSection.classList.add("hidden");
  }
}

// BOTAO COMEÇAR DO INÍCIO
if (startFromBeginningBtn) {
  startFromBeginningBtn.onclick = () => abrirLeitor(0);
}

// BOTAO VOLTAR PARA A SELEÇÃO
if (backToHomeBtn) {
  backToHomeBtn.onclick = () => {
    if (continueModal) continueModal.classList.remove("hidden");
  };
}

// LOGIN GOOGLE
if (googleLoginBtn && typeof auth !== "undefined") {
  googleLoginBtn.onclick = async function (e) {
    e.preventDefault();
    const provider = new firebase.auth.GoogleAuthProvider();
    try {
      await auth.signInWithPopup(provider);
    } catch (error) {
      if (error.code !== "auth/popup-closed-by-user") {
        console.error("Erro no login Google:", error);
        alert("Erro ao conectar com o Google. Tente novamente.");
      }
    }
  };
}

// ENTRAR COMO VISITANTE
if (guestBtn) {
  guestBtn.onclick = function (e) {
    e.preventDefault();
    modoVisitante = true;
    if (welcomeModal) welcomeModal.classList.add("hidden");

    const deviceId = obterOuCriarIdDispositivo();
    const paginaSalvaLocal = parseInt(localStorage.getItem(`pagina_${deviceId}`)) || 1;

    atualizarInterfaceSelecao(paginaSalvaLocal);

    if (continueModal) continueModal.classList.remove("hidden");
  };
}

// MONITOR DO FIREBASE AUTH
if (typeof auth !== "undefined") {
  auth.onAuthStateChanged(async (user) => {
    if (user) {
      usuarioAtual = user;
      modoVisitante = false;

      if (welcomeModal) welcomeModal.classList.add("hidden");

      let paginaSalva = 1;

      if (typeof db !== "undefined") {
        try {
          const userRef = db.collection("leitores").doc(user.uid);
          const userDoc = await userRef.get();

          if (userDoc.exists) {
            paginaSalva = userDoc.data().paginaAtual || 1;
          } else {
            await userRef.set({
              nome: user.displayName || "Leitor",
              email: user.email || "",
              paginaAtual: 1
            });
          }
        } catch (err) {
          console.error("Erro ao acessar Firestore:", err);
        }
      }

      atualizarInterfaceSelecao(paginaSalva);

      if (continueModal) continueModal.classList.remove("hidden");

    } else if (!modoVisitante) {
      if (welcomeModal) welcomeModal.classList.remove("hidden");
      if (continueModal) continueModal.classList.add("hidden");
    }
  });
}

// ABRIR O LEITOR
function abrirLeitor(indicePagina) {
  indiceAtual = indicePagina;
  if (continueModal) continueModal.classList.add("hidden");
  atualizarPagina();
}

// SALVAR PROGRESSO
function salvarProgressoAutomatico(numeroPagina) {
  if (usuarioAtual && !modoVisitante && typeof db !== "undefined") {
    db.collection("leitores").doc(usuarioAtual.uid).set({
      paginaAtual: numeroPagina
    }, { merge: true }).catch(err => console.error("Erro ao salvar progresso:", err));
  } else {
    const deviceId = obterOuCriarIdDispositivo();
    localStorage.setItem(`pagina_${deviceId}`, numeroPagina);
  }
}

// ATUALIZAR INTERFACE
function atualizarPagina() {
  const numeroPaginaAtual = indiceAtual + 1;

  if (pageNumElement) pageNumElement.textContent = numeroPaginaAtual;

  if (pageTextElement) {
    pageTextElement.innerText = (typeof textosPaginas !== "undefined" && textosPaginas[numeroPaginaAtual]) 
      ? textosPaginas[numeroPaginaAtual] 
      : "Sem texto para esta página.";
  }

  // Atualiza botões
  if (nextBtn) nextBtn.disabled = indiceAtual === 0;
  if (prevBtn) prevBtn.disabled = indiceAtual === TOTAL_PAGINAS - 1;

  salvarProgressoAutomatico(numeroPaginaAtual);
}

// BOTÕES DE NAVEGAÇÃO
if (prevBtn) {
  prevBtn.addEventListener("click", () => {
    if (indiceAtual < TOTAL_PAGINAS - 1) {
      indiceAtual++;
      atualizarPagina();
    }
  });
}

if (nextBtn) {
  nextBtn.addEventListener("click", () => {
    if (indiceAtual > 0) {
      indiceAtual--;
      atualizarPagina();
    }
  });
}

// TECLADO
document.addEventListener("keydown", (e) => {
  if (e.key === "ArrowLeft" && nextBtn) nextBtn.click();
  if (e.key === "ArrowRight" && prevBtn) prevBtn.click();
});

// GESTOS DE SWIPE (TOUCH)
let touchStartX = 0;
let touchEndX = 0;

if (swipeArea) {
  swipeArea.addEventListener("touchstart", (e) => {
    touchStartX = e.changedTouches[0].screenX;
  }, false);

  swipeArea.addEventListener("touchend", (e) => {
    touchEndX = e.changedTouches[0].screenX;
    if (touchStartX - touchEndX > 40 && prevBtn) prevBtn.click();
    if (touchEndX - touchStartX > 40 && nextBtn) nextBtn.click();
  }, false);
}

// ALTERNAR ENTRE MODO CLARO E MODO ESCURO
const themeToggleBtn = document.getElementById('theme-toggle-btn');

if (themeToggleBtn) {
  themeToggleBtn.addEventListener('click', () => {
    document.body.classList.toggle('light-mode');

    if (document.body.classList.contains('light-mode')) {
      themeToggleBtn.textContent = '🌙 Modo Escuro';
    } else {
      themeToggleBtn.textContent = '☀️ Modo Claro';
    }
  });
}